@pragma('vm:entry-point')
int nearestDollarFirst(List<int> centAmounts) {
  if (centAmounts.isEmpty) return -1;
  int centDist(int v) {
    int r = v % 100;
    return r < 50 ? r : 100 - r;
  }
  List<int> sorted = List<int>.from(centAmounts);
  sorted.sort((a, b) => centDist(a).compareTo(centDist(b)));
  return sorted.first;
}

@pragma('vm:entry-point')
void main() {
  assert(nearestDollarFirst([149, 251, 300, 175]) == 300);
  assert(nearestDollarFirst([110, 190, 155]) == 110);
  assert(nearestDollarFirst([]) == -1);
  print('All tests passed!');
}

tests:
