  final candidate = nearestDollarFirst;

  expect(candidate([149, 251, 300, 175]), 300);
  expect(candidate([110, 190, 155]), 110);
  expect(candidate([]), -1);
  expect(candidate([50]), 50);
  expect(candidate([100, 199, 205]), 100);
  expect(candidate([133, 167, 150]), 133);
  expect(candidate([301, 449, 400]), 400);
