@pragma('vm:entry-point')
double ruleComplianceScore(String password, List<String> forbiddenPatterns) {
  if (forbiddenPatterns.isEmpty) return 100.0;
  double _check(int index, int violations) {
    if (index == forbiddenPatterns.length) {
      int passed = forbiddenPatterns.length - violations;
      return (passed / forbiddenPatterns.length) * 100.0;
    }
    int newViolations = password.contains(forbiddenPatterns[index])
        ? violations + 1
        : violations;
    return _check(index + 1, newViolations);
  }
  return _check(0, 0);
}

@pragma('vm:entry-point')
void main() {
  assert(ruleComplianceScore('secure!', ['abc', 'xyz', '123', 'qwe']) == 100.0);
  assert(ruleComplianceScore('abcxyz', ['abc', 'xyz', '123', 'qwe']) == 50.0);
  assert(ruleComplianceScore('abc', []) == 100.0);
  print('All tests passed!');
}

