  expect(candidate(['Z9.1', 'Z9.01', 'Z9.001']).toString(), '{Z9.001: 1, Z9.01: 2, Z9.1: 3}');
  expect(candidate(['QA1', 'Q1', 'QB1']).toString(), '{Q1: 1, QA1: 2, QB1: 3}');
  expect(candidate(['A1.5']).toString(), '{A1.5: 1}');
  expect(candidate([]).toString(), '{}');
  expect(candidate(['A2', 'A10', 'A1']).toString(), '{A1: 1, A2: 2, A10: 3}');
  expect(candidate(['M100.5', 'M100', 'M99.9']).toString(), '{M99.9: 1, M100: 2, M100.5: 3}');
