int qrNumericBitCount(int digitCount) {
  int bits = 0;
  int remaining = digitCount;
  while (remaining >= 3) {
    bits += 10;
    remaining -= 3;
  }
  if (remaining == 2) {
    bits += 7;
  } else if (remaining == 1) {
    bits += 4;
  }
  return bits;
}

