@pragma('vm:entry-point')
int findNthRestockCandidate(List<List<int>> inventory, int n) {
  if (inventory.isEmpty || n < 0 || n >= inventory.length) return -1;

  List<List<int>> sorted = List<List<int>>.from(inventory);
  sorted.sort((a, b) {
    int aDeficit = a[2] - a[1];
    int bDeficit = b[2] - b[1];
    bool aBelow = aDeficit > 0;
    bool bBelow = bDeficit > 0;

    if (aBelow != bBelow) return aBelow ? -1 : 1;

    if (aBelow) {
      int aUrgency = aDeficit * a[3];
      int bUrgency = bDeficit * b[3];
      int cmp = bUrgency.compareTo(aUrgency);
      if (cmp != 0) return cmp;
    }

    return a[0].compareTo(b[0]);
  });

  return sorted[n][0];
}

@pragma('vm:entry-point')
