List<String> prioritizeBatteriesForReplacement(List<String> batterySpecs) {
  final result = List<String>.from(batterySpecs);
  result.sort((a, b) {
    final ap = a.split(':');
    final bp = b.split(':');
    final ac = int.parse(ap[1]);
    final bc = int.parse(bp[1]);
    final av = int.parse(ap[2]);
    final bv = int.parse(bp[2]);
    final cmp = (bc * av).compareTo(ac * bv);
    if (cmp != 0) return cmp;
    return ap[0].compareTo(bp[0]);
  });
  return result;
}

