@pragma('vm:entry-point')
double calculateTotalIngredient(String target, String currentRecipe, double portions, Map<String, Map<String, double>> recipeBook) {
  double traverse(String item, double multiplier, Set<String> visited) {
    if (item == target) {
      return multiplier;
    }

    if (!recipeBook.containsKey(item)) {
      return 0.0;
    }

    if (visited.contains(item)) {
      return -1.0; // Indicate cycle detection
    }

    visited.add(item);
    double total = 0.0;

    for (var entry in recipeBook[item]!.entries) {
      double subAmount = traverse(entry.key, multiplier * entry.value, visited);
      if (subAmount == -1.0) {
        return -1.0;
      }
      total += subAmount;
    }

    visited.remove(item);
    return total;
  }

  return traverse(currentRecipe, portions, <String>{});
}

