void main() {
  assert(calculateTotalIngredient('sugar', 'cake', 1.0, {'cake': {'batter': 1.0, 'frosting': 2.0}, 'batter': {'flour': 2.0, 'sugar': 1.5}, 'frosting': {'sugar': 0.5, 'butter': 0.25}}) == 2.5);
