@pragma('vm:entry-point')
List<int> sortByKingDistance(List<int> squares, int targetSquare) {
  final int targetRank = targetSquare ~/ 8;
  final int targetFile = targetSquare % 8;

  final List<int> result = List<int>.from(squares);
  result.sort((a, b) {
    final int aRank = a ~/ 8;
    final int aFile = a % 8;
    final int bRank = b ~/ 8;
    final int bFile = b % 8;

    final int adx = (aRank - targetRank).abs();
    final int ady = (aFile - targetFile).abs();
    final int bdx = (bRank - targetRank).abs();
    final int bdy = (bFile - targetFile).abs();

    final int aKing = adx > ady ? adx : ady;
    final int bKing = bdx > bdy ? bdx : bdy;

    if (aKing != bKing) {
      return aKing.compareTo(bKing);
    }

    final int aMan = adx + ady;
    final int bMan = bdx + bdy;

    if (aMan != bMan) {
      return aMan.compareTo(bMan);
    }

    return a.compareTo(b);
  });

  return result;
}

