@pragma('vm:entry-point')
Map<String, int> countElevatorRequestMoves(int startFloor, List<int> requests) {
  Map<String, int> walk(int index, int current) {
    if (index == requests.length) {
      return {'up': 0, 'down': 0, 'travel': 0};
    }
    final next = requests[index];
    final rest = walk(index + 1, next);
    final diff = next - current;
    rest['travel'] = rest['travel']! + diff.abs();
    if (diff > 0) rest['up'] = rest['up']! + 1;
    if (diff < 0) rest['down'] = rest['down']! + 1;
    return rest;
  }
  return walk(0, startFloor);
}

@pragma('vm:entry-point')
