  assert(countElevatorRequestMoves(0, [2, 5, 3]).toString() == '{up: 2, down: 1, travel: 7}');
  assert(countElevatorRequestMoves(4, <int>[]).toString() == '{up: 0, down: 0, travel: 0}');
