@pragma('vm:entry-point')
List<int> closePrecinctMargins(List<int> margins, int maxGap) {
  List<int> collect(int index) {
    if (index == margins.length) {
      return <int>[];
    }
    final int margin = margins[index];
    final int gap = margin < 0 ? -margin : margin;
    final List<int> rest = collect(index + 1);
    if (gap <= maxGap) {
      return <int>[margin, ...rest];
    }
    return rest;
  }
  return collect(0);
}

@pragma('vm:entry-point')
void main() {
  assert(closePrecinctMargins([12, -3, 0, 9], 3).toString() == '[-3, 0]');
  assert(closePrecinctMargins([], 5).isEmpty);
  assert(closePrecinctMargins([5, -5, 6], 5).length == 2);
