bool mazeCellsHaveEvenOpenings(List<int> cellMasks) {
  const int directionBits = 0xF;
  for (final cell in cellMasks) {
    int openings = cell & directionBits;
    openings ^= openings >> 2;
    openings ^= openings >> 1;
    if ((openings & 1) == 1) {
      return false;
    }
  }
  return true;
}

