Set<int> stableTelemetryRunEnds(List<int> samples, int tolerance, int minRunLength) {
  Set<int> ends = <int>{};
  if (samples.isEmpty) return ends;
  List<int> runLengths = List<int>.filled(samples.length, 1);
  if (minRunLength <= 1) ends.add(0);
  for (int i = 1; i < samples.length; i++) {
    int gap = (samples[i] - samples[i - 1]).abs();
    runLengths[i] = gap <= tolerance ? runLengths[i - 1] + 1 : 1;
    if (runLengths[i] >= minRunLength) ends.add(i);
  }
  return ends;
}

