@pragma('vm:entry-point')
int morseInversionCount(List<String> symbols) {
  // Custom comparator: returns true if a should come before or equal to b.
  bool lessOrEqual(String a, String b) {
    if (a.length != b.length) return a.length < b.length;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return a[i] == '.'; // '.' is less than '-'
      }
    }
    return true; // equal
  }

  // Work on a copy to avoid mutating the input.
  List<String> a = List.from(symbols);
  int n = a.length;
  if (n <= 1) return 0;
  List<String> temp = List.filled(n, '');

  // Recursive merge sort that returns inversion count.
  int mergeSort(int left, int right) {
    if (left >= right) return 0;
    int mid = (left + right) >> 1;
    int inv = mergeSort(left, mid) + mergeSort(mid + 1, right);
    int i = left, j = mid + 1, k = left;
    while (i <= mid && j <= right) {
      if (lessOrEqual(a[i], a[j])) {
        temp[k++] = a[i++];
      } else {
        temp[k++] = a[j++];
        inv += mid - i + 1;
      }
    }
    while (i <= mid) temp[k++] = a[i++];
    while (j <= right) temp[k++] = a[j++];
    for (i = left; i <= right; i++) a[i] = temp[i];
    return inv;
  }

  return mergeSort(0, n - 1);
}

@pragma('vm:entry-point')
void main() {
  assert(morseInversionCount([]) == 0);
  assert(morseInversionCount(["."]) == 0);
  assert(morseInversionCount(["-", "."]) == 1);
  print('All tests passed!');
}

