bool isScheduleStepCompliant(List<int> schedule, int step) {
  step = step.abs();
  if (step == 0) {
    for (int i = 1; i < schedule.length; i++) {
      if (schedule[i] != schedule[0]) return false;
    }
    return true;
  }
  for (int i = 1; i < schedule.length; i++) {
    if ((schedule[i] - schedule[i - 1]) % step != 0) return false;
  }
  return true;
}

