bool areSquaresSortedByFileThenRank(List<String> squares) {
  if (squares.length <= 1) return true;
  for (int i = 1; i < squares.length; i++) {
    String prev = squares[i - 1];
    String curr = squares[i];
    int prevFile = prev.codeUnitAt(0);
    int currFile = curr.codeUnitAt(0);
    if (prevFile != currFile) {
      if (prevFile > currFile) return false;
    } else {
      int prevRank = prev.codeUnitAt(1);
      int currRank = curr.codeUnitAt(1);
      if (prevRank > currRank) return false;
    }
  }
  return true;
}

