double averageBorderChargeCycles(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0.0;
  int rows = grid.length;
  int cols = grid[0].length;
  int sum = 0;
  int count = 0;
  for (int idx = 0; idx < rows * cols; idx++) {
    int i = idx ~/ cols;
    int j = idx % cols;
    if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
      sum += grid[i][j];
      count++;
    }
  }
  return sum / count;
}

