bool isTrafficLightChecksumValid(String sequence, int expectedChecksum) {
  int sum = 0;
  for (int i = 0; i < sequence.length; i++) {
    String c = sequence[i];
    if (c == 'R') {
      sum += 1;
    } else if (c == 'Y') {
      sum += 2;
    } else if (c == 'G') {
      sum += 3;
    }
  }
  int checksum = sum % 10;
  return checksum == expectedChecksum;
}

