List<int> collectLowStockQuantities(List<int> quantities, int threshold) {
  if (quantities.length <= 1) {
    if (quantities.isEmpty) return [];
    return quantities[0] < threshold ? [quantities[0]] : [];
  }
  int mid = quantities.length ~/ 2;
  List<int> left = collectLowStockQuantities(quantities.sublist(0, mid), threshold);
  List<int> right = collectLowStockQuantities(quantities.sublist(mid), threshold);
  return left..addAll(right);
}

