  expect(candidate([], []), 0);
  expect(candidate([3,1,4], []), 4);
  expect(candidate([0,0], ["INSERT 0"]), 1);
  expect(candidate([2], ["INSERT 0", "DELETE 0"]), 3);
  expect(candidate([5], ["BEGIN", "INSERT 0", "BEGIN", "INSERT 0", "ROLLBACK", "COMMIT"]), 7);
  expect(candidate([1,2], ["INSERT 0", "BEGIN", "INSERT 1", "DELETE 0", "ROLLBACK"]), 3);
  expect(candidate([0,0,0], ["INSERT 2", "INSERT 2", "DELETE 2"]), 2);
  expect(candidate([0], ["DELETE 0"]), 0);
