List<String> precinctWinnersWithTiebreak(List<List<int>> votes) {
  if (votes.isEmpty) return [];
  int numCandidates = votes[0].length;
  List<int> totalVotes = List<int>.filled(numCandidates, 0);
  for (var precinct in votes) {
    for (int i = 0; i < precinct.length; i++) {
      totalVotes[i] += precinct[i];
    }
  }
  List<String> results = [];
  for (var precinct in votes) {
    int maxVotes = precinct[0];
    for (int v in precinct) {
      if (v > maxVotes) maxVotes = v;
    }
    List<int> maxIndices = [];
    for (int i = 0; i < precinct.length; i++) {
      if (precinct[i] == maxVotes) maxIndices.add(i);
    }
    int winnerIndex;
    if (maxIndices.length == 1) {
      winnerIndex = maxIndices[0];
    } else {
      int bestTotal = -1;
      int bestIndex = -1;
      for (int idx in maxIndices) {
        if (totalVotes[idx] > bestTotal) {
          bestTotal = totalVotes[idx];
          bestIndex = idx;
        } else if (totalVotes[idx] == bestTotal && idx < bestIndex) {
          bestIndex = idx;
        }
      }
      winnerIndex = bestIndex;
    }
    results.add('Candidate $winnerIndex');
  }
  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(precinctWinnersWithTiebreak([]).toString() == '[]');
  assert(precinctWinnersWithTiebreak([[5]]).toString() == '[Candidate 0]');
