@pragma('vm:entry-point')
List<String> shuffleDeckGrid(List<List<String>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return [];
  final rows = grid.length;
  final cols = grid[0].length;
  final topCount = (rows + 1) ~/ 2;
  final top = grid.sublist(0, topCount);
  final bottom = grid.sublist(topCount);
  final newGrid = <List<String>>[];
  for (var i = 0; i < top.length || i < bottom.length; i++) {
    if (i < top.length) newGrid.add(top[i]);
    if (i < bottom.length) newGrid.add(bottom[i]);
  }
  final result = <String>[];
  var topRow = 0, bottomRow = rows - 1, leftCol = 0, rightCol = cols - 1;
  while (topRow <= bottomRow && leftCol <= rightCol) {
    for (var c = leftCol; c <= rightCol; c++) result.add(newGrid[topRow][c]);
    topRow++;
    for (var r = topRow; r <= bottomRow; r++) result.add(newGrid[r][rightCol]);
    rightCol--;
    if (topRow <= bottomRow) {
      for (var c = rightCol; c >= leftCol; c--) result.add(newGrid[bottomRow][c]);
      bottomRow--;
    }
    if (leftCol <= rightCol) {
      for (var r = bottomRow; r >= topRow; r--) result.add(newGrid[r][leftCol]);
      leftCol++;
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(shuffleDeckGrid([['AS']]).toString() == ['AS'].toString());
  assert(shuffleDeckGrid([['AS','2S'],['3S','4S']]).toString() == ['AS','2S','4S','3S'].toString());
  print('All tests passed!');
}

