@pragma('vm:entry-point')
double computeLogBucketGcdAverage(List<String> logLines) {
  final buckets = List.generate(16, (_) => <int>[]);

  for (final line in logLines) {
    final parts = line.split(' ');
    if (parts.length != 3) continue;
    final ts = int.tryParse(parts[0]);
    final rid = int.tryParse(parts[1]);
    final bytes = int.tryParse(parts[2]);
    if (ts == null || rid == null || bytes == null) continue;

    final bucketIndex = (ts ^ rid) & 15;
    buckets[bucketIndex].add(bytes);
  }

  int sumGcd = 0;
  int bucketCount = 0;

  for (final bucket in buckets) {
    if (bucket.length < 2) continue;

    int gcd = bucket[0];
    for (int i = 1; i < bucket.length; i++) {
      gcd = _gcd(gcd, bucket[i]);
      if (gcd == 1) break;
    }

    sumGcd += gcd;
    bucketCount++;
  }

  if (bucketCount == 0) return 0.0;
  return sumGcd / bucketCount;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

