void main() {
  assert(computeLogBucketGcdAverage([]) == 0.0);
  assert(computeLogBucketGcdAverage(["100 20 12"]) == 0.0);
  assert(computeLogBucketGcdAverage(["100 20 12", "116 4 18"]) == 6.0);
  print('All tests passed!');
}

