Set<int> findCombinableShelfCodes(List<int> shelfCodes) {
  final result = <int>{};
  final n = shelfCodes.length;
  for (int k = 0; k < n; k++) {
    final target = shelfCodes[k];
    int i = 0;
    int j = k - 1;
    while (i < j) {
      final sum = shelfCodes[i] + shelfCodes[j];
      if (sum == target) {
        result.add(target);
        break;
      } else if (sum < target) {
        i++;
      } else {
        j--;
      }
    }
  }
  return result;
}

