bool isMoistureLevelRowExclusive(List<List<int>> grid) {
  Map<int, Set<int>> moistureRows = {};
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      int moisture = grid[r][c];
      moistureRows.putIfAbsent(moisture, () => {}).add(r);
