@pragma('vm:entry-point')
int parseChessSquareIndex(String square) {
  int state = 0; // 0: expecting file letter, 1: expecting rank digit, 2: done
  int file = -1, rank = -1;

  for (int i = 0; i < square.length; i++) {
    int code = square.codeUnitAt(i);

    if (state == 0) {
      if (code >= 97 && code <= 104) { // 'a' to 'h'
        file = code - 97;
        state = 1;
      } else {
        return -1;
      }
    } else if (state == 1) {
      if (code >= 49 && code <= 56) { // '1' to '8'
        rank = code - 49;
        state = 2;
      } else {
        return -1;
      }
    } else {
      return -1; // extra characters
    }
  }

  return (state == 2) ? (file + rank * 8) : -1;
}

@pragma('vm:entry-point')
void main() {
  assert(parseChessSquareIndex('a1') == 0);
  assert(parseChessSquareIndex('h8') == 63);
  assert(parseChessSquareIndex('') == -1);
  print('All tests passed!');
}

