@pragma('vm:entry-point')
String checkPrimePowerPassword(String password) {
  String digits = '';
  for (int i = 0; i < password.length; i++) {
    if (password.codeUnitAt(i) >= 48 && password.codeUnitAt(i) <= 57) {
      digits += password[i];
    }
  }
  if (digits.isEmpty) {
    return 'No digits found';
  }
  int n = int.parse(digits);
  if (n == 0) {
    return 'Digits form 0: not a prime power';
  }
  if (n == 1) {
    return 'Digits form 1: not a prime power';
  }
  int original = n;
  int temp = n;
  int firstPrime = 0;
  int distinctPrimes = 0;
  int d = 2;
  while (d * d <= temp) {
    if (temp % d == 0) {
      if (firstPrime == 0) {
        firstPrime = d;
      } else if (d != firstPrime) {
        distinctPrimes++;
      }
      while (temp % d == 0) {
        temp ~/= d;
      }
    }
    d++;
  }
  if (temp > 1) {
    if (firstPrime != 0 && temp != firstPrime) {
      distinctPrimes++;
    } else if (firstPrime == 0) {
      firstPrime = temp;
    }
  }
  if (distinctPrimes == 0) {
    int exponent = 0;
    int m = original;
    while (m % firstPrime == 0) {
      m ~/= firstPrime;
      exponent++;
    }
    if (exponent == 1) {
      return 'Digits form $original: a prime number';
    } else {
      return 'Digits form $original: a prime power ($firstPrime^$exponent)';
    }
  } else {
    return 'Digits form $original: not a prime power';
  }
}

@pragma('vm:entry-point')
void main() {
  assert(checkPrimePowerPassword('abc123') == 'Digits form 123: not a prime power');
  assert(checkPrimePowerPassword('') == 'No digits found');
  assert(checkPrimePowerPassword('7') == 'Digits form 7: a prime number');
  print('All tests passed!');
}

