@pragma('vm:entry-point')
String highestTideAtHour(String readings) {
  if (readings.isEmpty) return '0:0';

  List<String> parts = readings.split(';');
  double maxHeight = double.negativeInfinity;
  int bestHour = 0;

  for (String part in parts) {
    if (part.isEmpty) continue;
    List<String> segments = part.split(',');
    double sum = 0;
    bool hasValid = false;

    for (String seg in segments) {
      if (seg.isEmpty) continue;
      List<String> pm = seg.split('+');
      if (pm.length != 2) continue;

      double base = double.tryParse(pm[0]) ?? 0;
      double multiplier = double.tryParse(pm[1]) ?? 0;
      if (base == 0 && multiplier == 0 && seg != '0+0') continue;

      sum += base * multiplier;
      hasValid = true;
    }

    if (!hasValid) continue;

    if (sum > maxHeight) {
      maxHeight = sum;
      bestHour = parts.indexOf(part);
    }
  }

  return '$bestHour:$maxHeight';
}

@pragma('vm:entry-point')
void main() {
  assert(highestTideAtHour('2+3,1+4;;5+2,3+1') == '2:13.0');
  assert(highestTideAtHour('0+0,1+1;2+2,0+3;1+5,0+0') == '2:5.0');
