double maxSmoothSegment(List<int> heights) {
  if (heights.isEmpty) return 0.0;
  int maxLen = 1;
  int curLen = 1;
  for (int i = 1; i < heights.length; i++) {
    int diff = heights[i] - heights[i - 1];
    if (diff.abs() <= 1) {
      curLen++;
      if (curLen > maxLen) maxLen = curLen;
    } else {
      curLen = 1;
    }
  }
  return maxLen.toDouble();
}

@pragma('vm:entry-point')
void main() {
  assert(maxSmoothSegment([3, 3, 4, 5, 7, 6, 5, 4]) == 6.0);
  assert(maxSmoothSegment([10, 8, 9, 9, 10, 10]) == 5.0);
  assert(maxSmoothSegment([]) == 0.0);
  print('All tests passed!');
}

