  assert(countSensorReadingsPerBin([], 0.0, 10.0).toString() == '{}');
  assert(countSensorReadingsPerBin(["A,5.0"], 0.0, 10.0).toString() == '{A_low: 0, A_medium: 1, A_high: 0}');
  assert(countSensorReadingsPerBin(["A,5.0", "B,15.0"], 0.0, 10.0).toString() == '{A_low: 0, A_medium: 1, A_high: 0, B_low: 0, B_medium: 0, B_high: 1}');
