int redundantBarcodeCheckDigit(String barcode) {
  int sum = 0;
  for (int i = 0; i < barcode.length; i++) {
    int digit = int.parse(barcode[i]);
    if (i % 2 == 0) {
      sum += digit * 3;
    } else {
      sum += digit;
    }
  }
  int checkDigit = (10 - (sum % 10)) % 10;
  return checkDigit;
}

