@pragma('vm:entry-point')
double passwordStrengthScore(String password) {
  if (password.isEmpty) return 0.0;
  int lower = 0, upper = 0, digit = 0, special = 0;
  for (int i = 0; i < password.length; i++) {
    String ch = password[i];
    if (ch.contains(RegExp(r'[a-z]'))) {
      lower++;
    } else if (ch.contains(RegExp(r'[A-Z]'))) {
      upper++;
    } else if (ch.contains(RegExp(r'[0-9]'))) {
      digit++;
    } else {
      special++;
    }
  }
  double base = password.length * 0.5;
  double bonus = (lower > 0 ? 1.0 : 0.0) + (upper > 0 ? 1.5 : 0.0) + (digit > 0 ? 1.0 : 0.0) + (special > 0 ? 2.0 : 0.0);
  return (base + bonus) < 10.0 ? (base + bonus) : 10.0;
}

@pragma('vm:entry-point')
void main() {
  assert(passwordStrengthScore("abc") == 2.5);
  assert(passwordStrengthScore("") == 0.0);
  assert(passwordStrengthScore("Ab1!") == 7.5);
  print('All tests passed!');
}

