@pragma('vm:entry-point')
Set<int> primeDiagonalCents(List<List<double>> grid) {
  Set<int> result = {};
  int rows = grid.length;
  if (rows == 0) return result;
  int cols = grid[0].length;
  if (cols == 0) return result;

  bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
      if (n % i == 0) return false;
    }
    return true;
  }

  int diagIndex = 0;
  for (int d = -(cols - 1); d <= rows - 1; d++) {
    double sum = 0.0;
    bool hasElem = false;
    for (int row = 0; row < rows; row++) {
      int col = row - d;
      if (col >= 0 && col < cols) {
        sum += grid[row][col];
        hasElem = true;
      }
    }
    if (!hasElem) continue;
    int roundedCents;
    if (isPrime(diagIndex)) {
      roundedCents = (sum * 100).floor();
    } else {
      roundedCents = (sum * 100).ceil();
    }
    result.add(roundedCents);
    diagIndex++;
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(primeDiagonalCents([]) == {});
  assert(primeDiagonalCents([[1.25]]) == {125});
  assert(primeDiagonalCents([[0.25, 0.50], [0.75, 1.00]]) == {25, 50, 75, 100});
  print('All tests passed!');
}

