@pragma('vm:entry-point')
double enclosedAreaFromDna(String sequence) {
  // If the sequence is empty, the area is trivially zero.
  if (sequence.isEmpty) return 0.0;

  // Map nucleotides to cardinal direction steps.
  int x = 0, y = 0;
  List<int> xs = [0];
  List<int> ys = [0];

  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];
    // Validate the character: only A, C, G, T are allowed.
    if (ch != 'A' && ch != 'C' && ch != 'G' && ch != 'T') {
      return 0.0; // invalid nucleotide
    }
    switch (ch) {
      case 'A': y++; break;   // north
      case 'C': y--; break;   // south
      case 'G': x++; break;   // east
      case 'T': x--; break;   // west
    }
    xs.add(x);
    ys.add(y);
  }

  // The path must end at the origin to form a closed polygon.
  if (x != 0 || y != 0) {
    return 0.0;
  }

  // Shoelace formula to compute signed area.
  double area = 0.0;
  for (int i = 0; i < xs.length - 1; i++) {
    area += (xs[i] * ys[i + 1] - xs[i + 1] * ys[i]).toDouble();
  }

  // Return absolute area (always a multiple of 0.5).
  return (area / 2.0).abs();
}

@pragma('vm:entry-point')
void main() {
  assert(enclosedAreaFromDna("") == 0.0);
  assert(enclosedAreaFromDna("AGCT") == 1.0);
  assert(enclosedAreaFromDna("AGCTAGCT") == 2.0);
  print('All tests passed!');
}

