bool canServiceAllRequestsOneWay(int currentFloor, List<int> requestedFloors) {
  int mask = 0;
  for (int f in requestedFloors) {
    mask |= (1 << f);
  }
  int maskAbove = 0;
  if (currentFloor < 31) {
    maskAbove = mask & ~((1 << (currentFloor + 1)) - 1);
  }
  int maskBelow = 0;
  if (currentFloor > 0) {
    maskBelow = mask & ((1 << currentFloor) - 1);
  }
  return maskAbove == 0 || maskBelow == 0;
}

