@pragma('vm:entry-point')
bool isPasswordAcceptable(String password, int minDistinctCategories, int minDigitSum) {
  if (password.length < 8) return false;
  int hasUpper = 0;
  int hasLower = 0;
  int hasDigit = 0;
  int hasSpecial = 0;
  int digitSum = 0;
  for (int i = 0; i < password.length; i++) {
    String ch = password[i];
    if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
      hasUpper = 1;
    } else if (ch.codeUnitAt(0) >= 97 && ch.codeUnitAt(0) <= 122) {
      hasLower = 1;
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      hasDigit = 1;
      digitSum += int.parse(ch);
    } else {
      hasSpecial = 1;
    }
    if (hasUpper + hasLower + hasDigit + hasSpecial >= minDistinctCategories && digitSum >= minDigitSum) {
      return true;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(isPasswordAcceptable("Abcdefg1", 3, 1) == true);
  assert(isPasswordAcceptable("abc", 2, 0) == false);
  assert(isPasswordAcceptable("ABCDEFGH", 2, 0) == false);
  print('All tests passed!');
