double averageMtuDeviation(List<int> packetSizes) {
  int sumDev = 0;
  int count = 0;
  for (final size in packetSizes) {
    if (size >= 64) {
      sumDev += (size - 1500).abs();
      count++;
    }
  }
  return count == 0 ? 0.0 : sumDev / count;
}

@pragma('vm:entry-point')
