int countCorrectionInitialGroups(List<String> words, Map<String, String> corrections, Set<String> priorityCorrections, int minFrequency) {
  Map<String, int> freq = {};
  for (var word in words) {
    if (corrections.containsKey(word)) {
      freq[word] = (freq[word] ?? 0) + 1;
    }
  }
  Set<String> firstLetters = {};
  for (var misspelled in freq.keys) {
    if (freq[misspelled]! >= minFrequency) {
      var correction = corrections[misspelled]!;
      if (priorityCorrections.contains(correction)) {
        if (correction.isNotEmpty) {
          firstLetters.add(correction[0]);
        }
      }
    }
  }
  return firstLetters.length;
}

