@pragma('vm:entry-point')
Map<String, int> countSierpinskiCarpetChars(int depth, String filledChar, String emptyChar) {
  if (depth == 0) {
    return {filledChar: 1, emptyChar: 0};
  }
  int subSize = 1;
  for (int i = 0; i < depth - 1; i++) {
    subSize *= 9;
  }
  Map<String, int> sub = countSierpinskiCarpetChars(depth - 1, filledChar, emptyChar);
  int subFilled = sub[filledChar]!;
  int subEmpty = sub[emptyChar]!;
  return {filledChar: 8 * subFilled, emptyChar: subSize + 8 * subEmpty};
}

