@pragma('vm:entry-point')
String bestWifiZone(List<List<int>> signalGrid, int minStrength) {
  if (signalGrid.isEmpty || signalGrid[0].isEmpty) {
    return 'No signal';
  }

  int rows = signalGrid.length;
  int cols = signalGrid[0].length;
  String bestZone = 'None';
  double bestScore = -1.0;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (signalGrid[r][c] >= minStrength) {
        int sum = 0;
        int count = 0;
        for (int i = r - 1; i <= r + 1; i++) {
          for (int j = c - 1; j <= c + 1; j++) {
            if (i >= 0 && i < rows && j >= 0 && j < cols) {
              sum += signalGrid[i][j];
              count++;
            }
          }
        }
        double avg = sum / count;
        if (avg > bestScore) {
          bestScore = avg;
          if (avg >= 80) {
            bestZone = 'Excellent';
          } else if (avg >= 60) {
            bestZone = 'Good';
          } else if (avg >= 40) {
            bestZone = 'Fair';
          } else {
            bestZone = 'Poor';
          }
        } else if (avg == bestScore) {
          String currentLabel;
          if (avg >= 80) {
            currentLabel = 'Excellent';
          } else if (avg >= 60) {
            currentLabel = 'Good';
          } else if (avg >= 40) {
            currentLabel = 'Fair';
          } else {
            currentLabel = 'Poor';
          }
          if (currentLabel == 'Excellent') {
            bestZone = currentLabel;
          } else if (currentLabel == 'Good' && bestZone != 'Excellent') {
            bestZone = currentLabel;
          } else if (currentLabel == 'Fair' && bestZone != 'Excellent' && bestZone != 'Good') {
            bestZone = currentLabel;
          } else if (currentLabel == 'Poor' && bestZone == 'None') {
            bestZone = currentLabel;
          }
        }
      }
    }
  }

  return bestScore == -1.0 ? 'No signal' : bestZone;
}

