List<int> simulateBatteryUndoLog(List<int> cycleDeltas) {
  final history = <int>[];
  final levels = <int>[];
  var level = 0;
  for (final d in cycleDeltas) {
    if (d == 0) {
      if (history.isNotEmpty) {
        level = history.removeLast();
      }
    } else {
      history.add(level);
      level += d;
    }
    levels.add(level);
  }
  return levels;
}

