Map<String, int> sumBarcodeDigitsByParity(String barcode) {
  var evenSum = 0;
  var oddSum = 0;
  for (var i = 0; i < barcode.length; i++) {
    final digit = int.tryParse(barcode[i]);
    if (digit == null) continue;
    if (i.isEven) {
      evenSum += digit;
    } else {
      oddSum += digit;
    }
  }
  return {'evenIndices': evenSum, 'oddIndices': oddSum};
}

