int maxCrossShelfPairs(List<int> leftShelfCodes, List<int> rightShelfCodes, int maxDiff) {
  int i = 0, j = 0, pairs = 0;
  while (i < leftShelfCodes.length && j < rightShelfCodes.length) {
    final diff = leftShelfCodes[i] - rightShelfCodes[j];
    if (diff.abs() <= maxDiff) {
      pairs++; i++; j++;
    } else if (leftShelfCodes[i] < rightShelfCodes[j]) {
      i++;
    } else {
      j++;
    }
  }
  return pairs;
}

