@pragma('vm:entry-point')
String trainTimetableUndoLog(List<String> log) {
  final stack = <int>[];
  var total = 0;
  for (final entry in log) {
    if (entry == 'UNDO') {
      if (stack.isNotEmpty) {
        total -= stack.removeLast();
      }
    } else {
      final minutes = int.parse(entry);
      total += minutes;
      stack.add(minutes);
    }
  }
  return total.toString();
}

@pragma('vm:entry-point')
void main() {
  assert(trainTimetableUndoLog(["10", "5"]) == "15");
  assert(trainTimetableUndoLog(["10", "UNDO", "3"]) == "3");
  assert(trainTimetableUndoLog([]) == "0");
  print('All tests passed!');
