  assert(findSharedPhaseDurations(["red", "red", "green", "green", "green", "red", "yellow", "yellow"]).length == 1);
  assert(findSharedPhaseDurations(["red", "red", "green", "green", "green", "red", "yellow", "yellow"]).contains(2));
