Map<String, int> summarizeBankLedger(String ledger) {
  var deposits = 0, withdrawals = 0, fees = 0, i = 0;
  while (i < ledger.length) {
    while (i < ledger.length && ledger[i] == ' ') i++;
    if (i >= ledger.length) break;
    var code = ledger[i++], amount = 0;
    while (i < ledger.length && ledger[i] != ' ') amount = amount * 10 + ledger[i++].codeUnitAt(0) - 48;
    if (code == 'D') deposits += amount;
    if (code == 'W') withdrawals += amount;
    if (code == 'F') fees += amount;
  }
  return {'deposits': deposits, 'withdrawals': withdrawals, 'fees': fees, 'netBalance': deposits - withdrawals - fees};
}

