@pragma('vm:entry-point')
Map<String, int> computeThermostatOverlapMetrics(List<int> zoneMasks) {
  int pc(int x) {
    x -= (x >> 1) & 0x55555555;
    x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
    x = (x + (x >> 4)) & 0x0F0F0F0F;
    x += x >> 8;
    x += x >> 16;
    return x & 0x3F;
  }

  List<int> layers = [];
  int unionMask = 0;

  for (int m in zoneMasks) {
    m &= 0xFFFFFF;
    if (m == 0) continue;
    for (int d = layers.length - 1; d >= 0; d--) {
      int overlap = layers[d] & m;
      if (overlap != 0) {
        if (d + 1 == layers.length) layers.add(0);
        layers[d + 1] |= overlap;
      }
    }
    if (layers.isEmpty) layers.add(0);
    layers[0] |= m;
    unionMask |= m;
  }

  int totalCoverage = pc(unionMask);
  int peakCount = layers.isEmpty ? 0 : layers.length;
  int peakMask = layers.isEmpty ? 0 : layers.last;
  int lowbit = peakMask & -peakMask;
  int peakHour = lowbit == 0 ? -1 : lowbit.bitLength - 1;
  int conflictHours = layers.length > 1 ? pc(layers[1]) : 0;

  int transMask = ((unionMask ^ ((unionMask << 1) & 0xFFFFFF)) >> 1) & 0x7FFFFF;
  int transitionCount = pc(transMask);

  int longestRun = 0;
  int run = unionMask;
  while (run != 0) {
    run &= run << 1;
    longestRun++;
  }

  return {
    'totalCoverage': totalCoverage,
    'peakDemandCount': peakCount,
    'peakDemandHour': peakHour,
    'conflictHours': conflictHours,
    'longestRun': longestRun,
    'transitionCount': transitionCount,
    'idleHours': 24 - totalCoverage,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(computeThermostatOverlapMetrics([]).toString() == '{totalCoverage: 0, peakDemandCount: 0, peakDemandHour: -1, conflictHours: 0, longestRun: 0, transitionCount: 0, idleHours: 24}');
  assert(computeThermostatOverlapMetrics([0xAAAAAA, 0xAAAAAA]).toString() == '{totalCoverage: 12, peakDemandCount: 2, peakDemandHour: 1, conflictHours: 12, longestRun: 1, transitionCount: 23, idleHours: 12}');
  assert(computeThermostatOverlapMetrics([0xFFFFFF]).toString() == '{totalCoverage: 24, peakDemandCount: 1, peakDemandHour: 0, conflictHours: 0, longestRun: 24, transitionCount: 0, idleHours: 0}');
  print('All tests passed!');
}

