double computePassWindowManhattanDistance(int groundX, int groundY, int windowX1, int windowY1, int windowX2, int windowY2) {
  final left = windowX1 < windowX2 ? windowX1 : windowX2;
  final right = windowX1 < windowX2 ? windowX2 : windowX1;
  final bottom = windowY1 < windowY2 ? windowY1 : windowY2;
  final top = windowY1 < windowY2 ? windowY2 : windowY1;

  final dx = groundX < left ? left - groundX : (groundX > right ? groundX - right : 0);
  final dy = groundY < bottom ? bottom - groundY : (groundY > top ? groundY - top : 0);

  return (dx + dy).toDouble();
}

