  assert(trainTimetableConvexHullArea([], [], 5) == 0.0);
  assert(trainTimetableConvexHullArea([0, 10], [10, 20], 5) == 50.0);
  assert(trainTimetableConvexHullArea([0, 0, 10, 10], [0, 10, 0, 10], 0) == 100.0);
  print('All tests passed!');
}

