@pragma('vm:entry-point')
double optimalMorseSegmentValue(String symbols) {
  // Simplified telegraph alphabet used by the operator.
  // Each pattern maps to its intrinsic transmission value.
  const alphabet = {
    '.': 1.0,
    '-': 1.5,
    '.-': 2.5,
    '-..': 2.75,
    '-...': 3.75,
    '-.-.': 5.0,
  };
  const gap = 0.5;

  final n = symbols.length;
  if (n == 0) return 0.0;

  // dp[i] keeps the best value achievable for the first i symbols.
  final dp = List<double>.filled(n + 1, double.negativeInfinity);
  dp[0] = 0.0;

  for (var i = 1; i <= n; i++) {
    for (final entry in alphabet.entries) {
      final pattern = entry.key;
      final value = entry.value;
      final len = pattern.length;
      if (len > i) continue;

      final chunk = symbols.substring(i - len, i);
      if (chunk != pattern) continue;

      final previous = dp[i - len];
      if (previous == double.negativeInfinity) continue;

      final penalty = (i - len > 0) ? gap : 0.0;
      final candidate = previous + value - penalty;

      if (candidate > dp[i]) {
        dp[i] = candidate;
      }
    }
  }

  return dp[n] == double.negativeInfinity ? 0.0 : dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(optimalMorseSegmentValue("") == 0.0);
  assert(optimalMorseSegmentValue(".-") == 2.5);
  assert(optimalMorseSegmentValue("-...-") == 4.75);
  print('All tests passed!');
}

