  expect(candidate("."), 1.0);
  expect(candidate(".-"), 2.5);
  expect(candidate("-.."), 2.75);
  expect(candidate("-.-."), 5.0);
  expect(candidate("-...-"), 4.75);
  expect(candidate("-.-.-"), 6.0);
  expect(candidate("--"), 2.5);
  expect(candidate("....."), 3.0);
}

