  expect(candidate(<String>['C:100', '[', 'D:50', ']']), <String>['OPEN', 'CLOSE:net=-50,result=100', 'FINAL:100']);
  expect(candidate(<String>['[', 'C:100', '[', 'D:50', ']', ']']), <String>['OPEN', 'OPEN', 'CLOSE:net=-50,result=100', 'CLOSE:net=100,result=100', 'FINAL:100']);
