Map<String, int> categorizeInventoryBins(List<int> binStatusCodes) {
  int occupied = 0;
  int damaged = 0;
  int reserved = 0;
  int climateControlled = 0;
  int highSecurity = 0;
  int availableClean = 0;
  int multiIssue = 0;

  for (int bin in binStatusCodes) {
    if ((bin & 1) != 0) occupied++;
    if ((bin & 2) != 0) damaged++;
    if ((bin & 4) != 0) reserved++;
    if ((bin & 8) != 0) climateControlled++;
    if ((bin & 16) != 0) highSecurity++;
    if ((bin & 7) == 0) availableClean++;
    if ((bin & 3) == 3) multiIssue++;
  }

  return {
    'occupied': occupied,
    'damaged': damaged,
    'reserved': reserved,
    'climateControlled': climateControlled,
    'highSecurity': highSecurity,
