@pragma('vm:entry-point')
List<String> exclusiveMazeCells(List<List<int>> rooms) {
  Map<String, int> cellCount = {};
  for (var room in rooms) {
    int r = room[0], c = room[1], h = room[2], w = room[3];
    for (int i = r; i < r + h; i++) {
      for (int j = c; j < c + w; j++) {
        String key = '$i,$j';
        cellCount[key] = (cellCount[key] ?? 0) + 1;
      }
    }
  }
  List<String> result = [];
  cellCount.forEach((key, count) {
    if (count == 1) {
      result.add(key);
    }
  });
  result.sort((a, b) {
    var pa = a.split(',').map(int.parse).toList();
    var pb = b.split(',').map(int.parse).toList();
    if (pa[0] != pb[0]) return pa[0].compareTo(pb[0]);
    return pa[1].compareTo(pb[1]);
  });
  return result;
}

