void main() {
  assert(computeShippingYardThroughput([]) == 0);
  assert(computeShippingYardThroughput(['LOAD:10', 'LOAD:20', 'COMBINE', 'SHIP']) == 30);
  assert(computeShippingYardThroughput(['LOAD:5', 'LOAD:10', 'LOAD:15', 'SHIP', 'CLEAR']) == 30);
