String normalizeFloorRequests(String input) {
  if (input.isEmpty) return '';
  Set<int> floors = {};
  for (var t in input.split(',')) {
    t = t.trim();
    if (t == 'G') floors.add(0);
    else if (t.startsWith('B')) floors.add(-int.parse(t.substring(1)));
    else floors.add(int.parse(t));
  }
  var sorted = floors.toList()..sort();
  return sorted.map((f) => f == 0 ? 'G' : f < 0 ? 'B${-f}' : '$f').join(',');
}

