  expect(candidate([[0, 0, 0], [2, 0, 0]], 10, 10), true);
  expect(candidate([[0, 0, 0], [1, 0, 0]], 10, 10), false);
  expect(candidate([[0, 0, 0], [5, 0, 0]], 10, 10), false);
