@pragma('vm:entry-point')
double findKthClosestLuminance(List<int> sortedLuminances, int target, int k) {
  final int n = sortedLuminances.length;
  if (k <= 0 || k > n) {
    return -1.0;
  }
  if (n == 1) {
    return sortedLuminances[0].toDouble();
  }
  // Binary search for the optimal window of k consecutive elements
  // that contains the k closest luminances to the target.
  // We find the smallest index i where the window [i, i+k-1] is optimal.
  // The decision: if sortedLuminances[i] + sortedLuminances[i+k] >= 2*target,
  // the element at i+k is farther from (or equidistant to) target than
  // the element at i, so the window should not shift right.
  int lo = 0;
  int hi = n - k;
  while (lo < hi) {
    final int mid = lo + (hi - lo) ~/ 2;
    final int leftVal = sortedLuminances[mid];
    final int rightVal = sortedLuminances[mid + k];
    if (leftVal + rightVal >= 2 * target) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  // The k-th closest is the farthest element within the chosen window.
  // Tie-break rule: when equidistant, smaller luminance ranks as closer,
  // so the k-th closest is the larger luminance (windowRight).
  final int windowLeft = sortedLuminances[lo];
  final int windowRight = sortedLuminances[lo + k - 1];
  final int distLeft = target - windowLeft;
  final int distRight = windowRight - target;
  if (distLeft > distRight) {
    return windowLeft.toDouble();
  }
  return windowRight.toDouble();
}

