void main() {
  assert(findKthClosestLuminance([10, 20, 30, 40, 50], 25, 3) == 10.0);
  assert(findKthClosestLuminance([10, 20, 30, 40, 50], 35, 2) == 40.0);
  assert(findKthClosestLuminance([128], 200, 1) == 128.0);
  print('All tests passed!');
}

