Map<String, int> countTrafficLightRuns(String sequence) {
  Map<String, int> runs = {"Red": 0, "Yellow": 0, "Green": 0};
  if (sequence.isEmpty) return runs;
  Map<String, String> phaseName = {"R": "Red", "Y": "Yellow", "G": "Green"};
  String? lastPhase;
  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];
    if (ch != lastPhase && phaseName.containsKey(ch)) {
      String name = phaseName[ch]!;
      runs[name] = runs[name]! + 1;
      lastPhase = ch;
    }
  }
  return runs;
}

