  assert(segmentTelemetry([10], 1).toString() == '[0:0]');
  assert(segmentTelemetry([], 1).toString() == '[]');
  assert(segmentTelemetry([1, 2, 3], 3).toString() == '[0:0, 1:1, 2:2]');
  print('All tests passed!');
}

