List<int> consistentMoistureLevels(List<List<int>> grid, int minRows) {
  final Map<int, Set<int>> valueToRows = {};
  final Map<int, int> valueToFreq = {};
  for (int r = 0; r < grid.length; r++) {
    for (final int val in grid[r]) {
      valueToRows.putIfAbsent(val, () => <int>{}).add(r);
      valueToFreq[val] = (valueToFreq[val] ?? 0) + 1;
    }
  }
  final List<int> result = [];
  valueToRows.forEach((int val, Set<int> rows) {
    if (rows.length >= minRows && valueToFreq[val] == rows.length) {
      result.add(val);
    }
  });
  result.sort();
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(consistentMoistureLevels([[1,2,3],[2,3,4],[3,4,5]], 2).toString() == '[2, 3, 4]');
  assert(consistentMoistureLevels([[1,1],[1,2]], 1).toString() == '[2]');
  assert(consistentMoistureLevels(<List<int>>[], 1).isEmpty);
  print('All tests passed!');
}

