@pragma('vm:entry-point')
Map<String, int> analyzeCashRounding(List<int> pricesInCents, int denomination) {
  int roundedUp = 0;
  int roundedDown = 0;
  int unchanged = 0;
  int totalAdjustment = 0;
  int g = 0;

  for (int price in pricesInCents) {
    int a = g;
    int b = price;
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    g = a;

    int rem = price % denomination;
    if (rem == 0) {
      unchanged++;
    } else if (2 * rem < denomination) {
      roundedDown++;
      totalAdjustment -= rem;
    } else {
      roundedUp++;
      totalAdjustment += denomination - rem;
    }
  }

  return {
    'rounded_up': roundedUp,
    'rounded_down': roundedDown,
    'unchanged': unchanged,
    'total_adjustment': totalAdjustment,
    'gcd': g,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeCashRounding([101, 102, 103, 104, 105], 5).toString() == '{rounded_up: 2, rounded_down: 2, unchanged: 1, total_adjustment: 0, gcd: 1}');
  assert(analyzeCashRounding([100, 200, 300], 5).toString() == '{rounded_up: 0, rounded_down: 0, unchanged: 3, total_adjustment: 0, gcd: 100}');
