Set<int> findDegradedCells(int cellCount, List<int> chargeCycles, int minTotalActive, int minConsecutivePairs) {
  Set<int> degraded = {};
  int numCycles = chargeCycles.length;
  if (numCycles == 0 || cellCount <= 0) {
    return degraded;
  }
  for (int cell = 0; cell < cellCount; cell++) {
    int history = 0;
    for (int j = 0; j < numCycles; j++) {
      if (((chargeCycles[j] >> cell) & 1) == 1) {
        history |= (1 << j);
      }
    }
    int totalActive = 0;
    int temp = history;
    while (temp != 0) {
      totalActive += temp & 1;
      temp >>= 1;
    }
    int paired = history & (history >> 1);
    int consecutivePairs = 0;
    temp = paired;
    while (temp != 0) {
      consecutivePairs += temp & 1;
      temp >>= 1;
    }
    if (totalActive >= minTotalActive && consecutivePairs >= minConsecutivePairs) {
      degraded.add(cell);
    }
  }
  return degraded;
}

