  expect(candidate([[[-2, -2]]]).toString(), '[union:4]');
  expect(candidate([[[2, 2]], [[1, 1], [1, 1]]]).toString(), '[union:4, 0-1:4]');
  expect(candidate([[[3, 3], [-3, -3]], [[-3, -3]]]).toString(), '[union:18]');
