Map<String, int> trainTimetableGcd(List<int> intervals) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  if (intervals.isEmpty) {
    return {"gcd": 0, "max": 0, "min": 0, "count": 0};
  }
  int g = intervals[0];
  int hi = intervals[0];
  int lo = intervals[0];
  for (int i = 1; i < intervals.length; i++) {
    g = gcd(g, intervals[i]);
    if (intervals[i] > hi) hi = intervals[i];
    if (intervals[i] < lo) lo = intervals[i];
  }
  return {"gcd": g, "max": hi, "min": lo, "count": intervals.length};
}

