List<int> dnaBoundingBoxAreas(List<String> sequences) {
  List<int> results = [];
  for (String seq in sequences) {
    int x = 0;
    int y = 0;
    int minX = 0;
    int maxX = 0;
    int minY = 0;
    int maxY = 0;
    for (int i = 0; i < seq.length; i++) {
      String base = seq[i];
      if (base == 'A') {
        y += 1;
      } else if (base == 'T') {
        y -= 1;
      } else if (base == 'G') {
        x += 1;
      } else if (base == 'C') {
        x -= 1;
      }
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
    int width = maxX - minX + 1;
    int height = maxY - minY + 1;
    results.add(width * height);
  }
  return results;
}

