@pragma('vm:entry-point')
List<int> barcodeScanOptimize(List<List<int>> grid, int penalty) {
  if (grid.isEmpty) return [];
  int rows = grid.length;
  int cols = grid[0].length;
  if (cols == 0) return [];

  // Validate all rows have the same length
  for (int r = 0; r < rows; r++) {
    if (grid[r].length != cols) return [];
  }

  // dp[r] = max score from current column rightward, starting at row r
  List<int> dp = List<int>.generate(rows, (r) => grid[r][cols - 1]);

  // Iterate columns right-to-left building optimal substructure
  for (int c = cols - 2; c >= 0; c--) {
    List<int> nextDp = List<int>.filled(rows, -1000000000);
    for (int r = 0; r < rows; r++) {
      int currentDigit = grid[r][c];
      // Scanner head can drift at most one row between columns
      int minNextRow = (r - 1 >= 0) ? r - 1 : 0;
      int maxNextRow = (r + 1 < rows) ? r + 1 : rows - 1;

      for (int nr = minNextRow; nr <= maxNextRow; nr++) {
        int nextDigit = grid[nr][c + 1];
        // Penalize repeated adjacent digits (scan echo artifact)
        int transitionPenalty = (currentDigit == nextDigit) ? penalty : 0;
        int candidateScore = currentDigit + dp[nr] - transitionPenalty;
        if (candidateScore > nextDp[r]) {
          nextDp[r] = candidateScore;
        }
      }
    }
    dp = nextDp;
  }

  return dp;
}

@pragma('vm:entry-point')
void main() {
  assert(barcodeScanOptimize([[1, 2], [3, 4]], 0).toString() == '[5, 7]');
  assert(barcodeScanOptimize([[9]], 100).toString() == '[9]');
  assert(barcodeScanOptimize([[5], [3], [7]], 0).toString() == '[5, 3, 7]');
  print('All tests passed!');
}

