@pragma('vm:entry-point')
int findKthMissingCard(List<int> hand, int k) {
  if (hand.isEmpty) {
    return k;
  }
  int totalMissing = hand[hand.length - 1] - hand.length;
  if (totalMissing < k) {
    return hand[hand.length - 1] + (k - totalMissing);
  }
  int left = 0;
  int right = hand.length - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    int missing = hand[mid] - (mid + 1);
    if (missing < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left == 0) {
    return k;
  }
  int missingBefore = hand[left - 1] - left;
  return hand[left - 1] + (k - missingBefore);
}

@pragma('vm:entry-point')
void main() {
  assert(findKthMissingCard([1, 3, 5, 8], 2) == 4);
  assert(findKthMissingCard([], 3) == 3);
  assert(findKthMissingCard([2, 4, 6], 1) == 1);
  print('All tests passed!');
}

