Set<int> findMatchingBorderRows(List<String> rows) {
  Set<int> result = {};
  for (int i = 0; i < rows.length; i++) {
    String row = rows[i];
    int left = 0;
    int right = row.length - 1;
    while (left < row.length && row[left] == ' ') left++;
    while (right >= 0 && row[right] == ' ') right--;
    if (left <= right && row[left] == row[right]) {
      result.add(i);
