void main() {
  assert(organizeShelfCodes(["A-4-10", "A-9-5", "B-4-3", "B-4-12"]).toString() == "[A-4-10, A-9-5, B-4-3, B-4-12]");
  assert(organizeShelfCodes([]).toString() == "[]");
  assert(organizeShelfCodes(["A-1-5", "A-2-5", "A-1-3"]).toString() == "[A-1-3, A-1-5, A-2-5]");
