List<String> decodeTideReadings(List<int> readings) {
  List<String> results = [];
  for (int r in readings) {
    if ((r & 4) == 0) continue;
    int height = (r >> 3) & 31;
    bool rising = (r & 1) == 1;
    bool extreme = (r & 2) == 2;
