@pragma('vm:entry-point')
bool hasBucketFixedPoint(List<int> counts) {
  if (counts.isEmpty) return false;

  bool search(int lo, int hi) {
    if (lo > hi) return false;

    int mid = lo + (hi - lo) ~/ 2;
    int midVal = counts[mid];

    if (midVal == mid) return true;

    // Prune left search range
    // For left side (indices lo..mid-1), since counts is sorted,
    // counts[j] <= midVal for all j <= mid. If counts[j] == j,
    // then j = counts[j] <= midVal. So only check up to min(mid-1, midVal).
    int leftHi;
    if (mid - 1 < midVal) {
      leftHi = mid - 1;
    } else {
      leftHi = midVal;
    }

    // Prune right search range
    // For right side (indices mid+1..hi), since counts is sorted,
    // counts[j] >= midVal for all j >= mid. If counts[j] == j,
    // then j = counts[j] >= midVal. So only check from max(mid+1, midVal).
    int rightLo;
    if (mid + 1 > midVal) {
      rightLo = mid + 1;
    } else {
      rightLo = midVal;
    }

    // Search left first, then right (short-circuit)
    if (search(lo, leftHi)) return true;
    return search(rightLo, hi);
  }

  return search(0, counts.length - 1);
}

