@pragma('vm:entry-point')
double computeShelfResonanceFrequency(int code) {
  if (code <= 1) return 0.0;

  // Find all divisors of code that are greater than 1
  List<int> divisors = [];
  for (int i = 2; i * i <= code; i++) {
    if (code % i == 0) {
      divisors.add(i);
      int complement = code ~/ i;
      if (complement != i) {
        divisors.add(complement);
      }
    }
  }
  divisors.add(code);

  // For each divisor, find its largest prime factor and accumulate mod 4
  int modSum = 0;
  for (int d in divisors) {
    int temp = d;
    int largestPrime = 1;

    // Check factor of 2
    if (temp % 2 == 0) {
      largestPrime = 2;
      while (temp % 2 == 0) {
        temp ~/= 2;
      }
    }

    // Check odd factors
    for (int p = 3; p * p <= temp; p += 2) {
      if (temp % p == 0) {
        largestPrime = p;
        while (temp % p == 0) {
          temp ~/= p;
        }
      }
    }

    // If remaining temp is a prime greater than 1
    if (temp > 1) {
      largestPrime = temp;
    }

    modSum += largestPrime % 4;
  }

  return modSum / 4.0;
}

