@pragma('vm:entry-point')
double minimizeShippingCost(List<int> weights, int maxBatchSize) {
  int n = weights.length;
  if (n == 0) return 0.0;
  List<double> dp = List<double>.filled(n + 1, double.infinity);
  dp[0] = 0.0;
  for (int i = 1; i <= n; i++) {
    int maxW = 0;
    for (int j = i - 1; j >= 0 && (i - j) <= maxBatchSize; j--) {
      if (weights[j] > maxW) maxW = weights[j];
      int count = i - j;
      double cost = dp[j] + count * maxW * 0.5;
      if (cost < dp[i]) dp[i] = cost;
    }
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(minimizeShippingCost([3, 1, 4], 2) == 4.0);
  assert(minimizeShippingCost([2, 5, 3, 1], 3) == 5.5);
  assert(minimizeShippingCost([], 2) == 0.0);
  print('All tests passed!');
}

