@pragma('vm:entry-point')
int decodeQrFormatInfo(int corrupted) {
  // QR format info: BCH(15,5) with generator 0x537,
  // XOR mask 0x5412. Recovers the 5-bit data payload
  // from a potentially corrupted 15-bit format string.
  int bestData = 0;
  int minDist = 16;
  for (int data = 0; data < 32; data++) {
    // BCH encode: compute remainder of (data << 10) / generator
    int rem = data << 10;
    for (int i = 14; i >= 10; i--) {
      if ((rem & (1 << i)) != 0) {
        rem ^= 0x537 << (i - 10);
      }
    }
    // Combine data and remainder, apply XOR mask
    int encoded = ((data << 10) | rem) ^ 0x5412;
    // Compute Hamming distance via popcount of XOR
    int diff = corrupted ^ encoded;
    int dist = 0;
    while (diff != 0) {
      diff &= diff - 1;
      dist++;
    }
    if (dist < minDist) {
      minDist = dist;
      bestData = data;
    }
  }
  return bestData;
}

