List<int> extractDashSegments(List<String> rows) {
  List<int> result = [];
  for (String row in rows) {
    int state = 0;
    int acc = 0;
    for (int i = 0; i < row.length; i++) {
      String c = row[i];
      if (state == 0) {
        if (c == '+') {
          state = 1;
          acc = 0;
        }
      } else {
        if (c == '-') {
          acc++;
        } else if (c == '+') {
          if (acc > 0) result.add(acc);
          acc = 0;
        } else {
          state = 0;
        }
      }
    }
  }
  return result;
}

