bool validateBatchDistribution(List<int> batchSizes, int shelves) {
  if (shelves <= 0) return false;
  if (batchSizes.isEmpty) return true;
  for (int i = 0; i < batchSizes.length; i++) {
    int batch = batchSizes[i];
    if (batch < 0) return false;
    if (batch % shelves != 0) return false;
    int quotient = batch ~/ shelves;
    int a = quotient;
    int b = shelves;
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    if (a != 1) return false;
  }
  return true;
}

