Map<String, int> countBorderLogLevels(List<List<String>> logGrid) {
  Map<String, int> counts = {};
  if (logGrid.isEmpty || logGrid[0].isEmpty) return counts;
  int rows = logGrid.length;
  int cols = logGrid[0].length;
  for (int r = 0; r < rows; r++) {
