@pragma('vm:entry-point')
List<int> findWinningCoalitions(List<int> margins, int threshold) {
  List<int> results = [];
  void backtrack(int index, int currentSum, int count, List<int> chosen) {
    if (currentSum >= threshold) {
      bool minimal = true;
      for (int v in chosen) {
        if (currentSum - v >= threshold) {
          minimal = false;
          break;
        }
      }
      if (minimal) {
        results.add(count);
      }
      return;
    }
    if (index >= margins.length) return;
    backtrack(index + 1, currentSum, count, chosen);
    chosen.add(margins[index]);
    backtrack(index + 1, currentSum + margins[index], count + 1, chosen);
    chosen.removeLast();
  }
  backtrack(0, 0, 0, []);
  results.sort();
  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(findWinningCoalitions([10], 5).toString() == '[1]');
  assert(findWinningCoalitions([7, 3, 2], 5).toString() == '[1, 2]');
  assert(findWinningCoalitions([2, 3], 10).toString() == '[]');
