int qrNumericBits(int digitCount) {
  int groups = digitCount ~/ 3;
  int remainder = digitCount % 3;
  int bits = groups * 10;
  if (remainder == 2) {
    bits += 7;
  } else if (remainder == 1) {
    bits += 4;
  }
  return bits;
}

