bool validateMoistureSensorGrid(List<String> events) {
  List<int> stack = [];
  for (String event in events) {
    if (event.startsWith('open_')) {
      int zone = int.parse(event.substring(5));
      stack.add(zone);
    } else if (event.startsWith('close_')) {
      int zone = int.parse(event.substring(6));
      if (stack.isEmpty || stack.removeLast() != zone) return false;
    }
  }
  return stack.isEmpty;
}

