@pragma('vm:entry-point')
bool simulateBucketAllocations(List<String> ops, int numBuckets, int maxLoad) {
  List<int> counts = List.filled(numBuckets, 0);
  List<List<String>> undoLogs = List.generate(numBuckets, (_) => []);
  int curr = 0;

  for (String op in ops) {
    if (op == 'ALLOC') {
      if (counts[curr] >= maxLoad) return false;
      counts[curr]++;
      undoLogs[curr].add('ALLOC');
    } else if (op == 'FREE') {
      if (counts[curr] <= 0) return false;
      counts[curr]--;
      undoLogs[curr].add('FREE');
    } else if (op == 'NEXT') {
      curr = (curr + 1) % numBuckets;
    } else if (op == 'PREV') {
      curr = (curr - 1 + numBuckets) % numBuckets;
    } else if (op == 'UNDO') {
      if (undoLogs[curr].isNotEmpty) {
        String lastOp = undoLogs[curr].removeLast();
        if (lastOp == 'ALLOC') {
          counts[curr]--;
        } else if (lastOp == 'FREE') {
          counts[curr]++;
        }
      }
    } else {
      return false;
    }
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(simulateBucketAllocations(['ALLOC', 'NEXT', 'ALLOC', 'UNDO', 'NEXT', 'FREE'], 3, 2) == false);
  assert(simulateBucketAllocations(['ALLOC', 'UNDO', 'NEXT', 'ALLOC'], 2, 1) == true);
  print('All tests passed!');
}

