@pragma('vm:entry-point')
List<int> parseModifiedRoundMaxSums(String roundLog) {
  List<int> results = [];
  RegExp pattern = RegExp(
    r'^R([1-9][0-9]*)\s*:\s*([1-9][0-9]?)d(4|6|8|10|12|20)$',
    caseSensitive: false,
  );

  for (String raw in roundLog.split(',')) {
    String token = raw.trim();
    if (token.isEmpty) continue;

    Match? match = pattern.firstMatch(token);
    if (match != null) {
      int roundNum = int.parse(match.group(1)!);
      int count = int.parse(match.group(2)!);
      int sides = int.parse(match.group(3)!);

      int maxSum = count * sides;
      if (roundNum % 2 == 0) {
        results.add(maxSum * 2);
      } else {
        results.add(maxSum);
      }
    }
  }
  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(parseModifiedRoundMaxSums('R1:3d6, R2:2d4').toString() == '[18, 16]');
  assert(parseModifiedRoundMaxSums('R5:1d20').toString() == '[20]');
