bool isValidBarcodeDuration(List<int> barcode, int startDay, int intervalDays) {
  if (barcode.length < 2 || startDay < 1 || intervalDays < 1) {
    return false;
  }
  int weightedSum = 0;
  for (int i = 0; i < barcode.length - 1; i++) {
    if (barcode[i] < 0 || barcode[i] > 9) return false;
    int dayIndex = startDay + (i * intervalDays);
    weightedSum += barcode[i] * dayIndex;
  }
  if (barcode.last < 0 || barcode.last > 9) return false;
  return (weightedSum % 10) == barcode.last;
}

