void main() {
  assert(findKthShortestMashup([1, 2, 3, 4], 3).toString() == '{mashupDuration: 5, pairCount: 2}');
  assert(findKthShortestMashup([10, 20], 1).toString() == '{mashupDuration: 30, pairCount: 1}');
