int earliestLongestPassStart(List<List<int>> passes) {
  if (passes.isEmpty) return -1;
  List<List<int>> sorted = [...passes];
  sorted.sort((a, b) {
    int durA = a[1] - a[0];
    int durB = b[1] - b[0];
    if (durA != durB) return durB.compareTo(durA);
    return a[0].compareTo(b[0]);
  });
  return sorted[0][0];
}

