int countDestinationsWithThreeIdenticalShipments(List<String> manifest) {
  final Map<String, int> counts = {};
  final Map<String, Set<int>> weights = {};

  for (final entry in manifest) {
    final parts = entry.split(':');
    if (parts.length != 2) continue;
    final dest = parts[0];
    final weight = int.parse(parts[1]);

    counts[dest] = (counts[dest] ?? 0) + 1;
    weights.putIfAbsent(dest, () => <int>{}).add(weight);
  }

  int qualifyingCount = 0;
  for (final dest in counts.keys) {
    if (counts[dest] == 3 && weights[dest]!.length == 1) {
      qualifyingCount++;
    }
  }
  return qualifyingCount;
}

