@pragma('vm:entry-point')
int countTrainDeparturesOnDay(int firstDepartureAbsoluteMinute, int intervalMinutes, int targetDayIndex) {
  int dayStart = targetDayIndex * 1440;
  int dayEnd = dayStart + 1439;
  if (dayEnd < firstDepartureAbsoluteMinute) {
    return 0;
  }
  int startK = 0;
  if (dayStart > firstDepartureAbsoluteMinute) {
    int diff = dayStart - firstDepartureAbsoluteMinute;
    startK = (diff + intervalMinutes - 1) ~/ intervalMinutes;
  }
  int endK = (dayEnd - firstDepartureAbsoluteMinute) ~/ intervalMinutes;
  if (endK < startK) {
    return 0;
  }
  return endK - startK + 1;
}

