Map<String, int> countInteriorNeighborsOfOpenPath(String maze) {
  Map<String, int> counts = {};
  if (maze.isEmpty) return counts;

  List<String> rawRows = maze.replaceAll('\r', '').split('\n');
  List<String> rows = rawRows.where((r) => r.isNotEmpty).toList();
  int numRows = rows.length;
  if (numRows < 3) return counts;

  List<List<String>> grid = [];
  int numCols = -1;
  for (String row in rows) {
    List<String> cells = row.split('|');
    if (numCols == -1) numCols = cells.length;
    if (cells.length == numCols) grid.add(cells);
  }

  if (numCols < 3) return counts;

  for (int r = 1; r < numRows - 1; r++) {
    for (int c = 1; c < numCols - 1; c++) {
      String cell = grid[r][c];
      if (cell == '.') continue;

      bool adjacent = grid[r - 1][c] == '.' ||
          grid[r + 1][c] == '.' ||
          grid[r][c - 1] == '.' ||
          grid[r][c + 1] == '.';

      if (adjacent) {
        counts[cell] = (counts[cell] ?? 0) + 1;
      }
    }
  }
  return counts;
}

