@pragma('vm:entry-point')
Map<String, int> processBankLedger(List<String> operations) {
  Map<String, int> balances = {};
  List<String> history = [];
  for (String op in operations) {
    if (op == 'UNDO') {
      if (history.isNotEmpty) {
        String lastOp = history.removeLast();
        List<String> parts = lastOp.split(':');
        String type = parts[0];
        String account = parts[1];
        int amount = int.parse(parts[2]);
        if (type == 'DEPOSIT') {
          balances[account] = (balances[account] ?? 0) - amount;
        } else if (type == 'WITHDRAW') {
          balances[account] = (balances[account] ?? 0) + amount;
        }
      }
    } else {
      List<String> parts = op.split(':');
      String type = parts[0];
      String account = parts[1];
      int amount = int.parse(parts[2]);
      if (type == 'DEPOSIT') {
        balances[account] = (balances[account] ?? 0) + amount;
        history.add(op);
      } else if (type == 'WITHDRAW') {
        int current = balances[account] ?? 0;
        if (current >= amount) {
          balances[account] = current - amount;
          history.add(op);
        }
      }
    }
  }
  return balances;
}

@pragma('vm:entry-point')
void main() {
  assert(processBankLedger([]).isEmpty);
  assert(processBankLedger(['DEPOSIT:Alice:100'])['Alice'] == 100);
  assert(processBankLedger(['DEPOSIT:Bob:50', 'WITHDRAW:Bob:100'])['Bob'] == 50);
  print('All tests passed!');
}

