@pragma('vm:entry-point')
List<String> summarizeTideZones(List<double> readings) {
  if (readings.isEmpty) return [];

  List<String> result = [];
  String getZone(double h) => h < 0.0 ? "subzero" : (h < 1.5 ? "shallow" : "deep");

  String currentZone = getZone(readings[0]);
  int count = 1;
  double prev = readings[0];

  for (int i = 1; i < readings.length; i++) {
    if (readings[i] == prev) {
      continue;
    }
    prev = readings[i];
    String zone = getZone(prev);
    if (zone == currentZone) {
      count++;
    } else {
      result.add("$currentZone:$count");
      currentZone = zone;
      count = 1;
    }
  }
  result.add("$currentZone:$count");
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(summarizeTideZones([]).toString() == "[]");
  assert(summarizeTideZones([1.0]).length == 1);
  assert(summarizeTideZones([2.0, 2.0, -0.5]).toString() == "[deep:1, subzero:1]");
  print('All tests passed!');
}

tests:
