  expect(summarizeTideZones([-1.5, -1.5, -0.5, 0.0, 1.5, 1.5, 3.0]), ["subzero:2", "shallow:1", "deep:2"]);
  expect(summarizeTideZones([-0.5, 0.5, 1.5, 2.0, 1.0, -0.5]), ["subzero:1", "shallow:1", "deep:2", "shallow:1", "subzero:1"]);
