bool hasValidConsecutiveLogSequence(List<int> serverLogDays, int requiredConsecutiveDays, int daysInCalendar) {
  if (requiredConsecutiveDays <= 0) return true;
  if (serverLogDays.isEmpty) return false;
  if (daysInCalendar <= 0) return false;

  final uniqueDays = <int>{};
  for (final day in serverLogDays) {
    if (day >= 0 && day < daysInCalendar) {
      uniqueDays.add(day);
    }
  }

  if (uniqueDays.length < requiredConsecutiveDays) return false;

  for (int start = 0; start < daysInCalendar; start++) {
    int count = 0;
    int current = start;
    while (uniqueDays.contains(current)) {
      count++;
      if (count >= requiredConsecutiveDays) return true;
      current = (current + 1) % daysInCalendar;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasValidConsecutiveLogSequence([364, 365, 0, 1, 2], 5, 366) == true);
  assert(hasValidConsecutiveLogSequence([10, 20, 30], 2, 366) == false);
  assert(hasValidConsecutiveLogSequence([], 1, 366) == false);
  print('All tests passed!');
}

tests:
