  final candidate = hasValidConsecutiveLogSequence;

  expect(candidate([10, 11, 12, 13], 4, 366), true);
  expect(candidate([364, 365, 0, 1, 2], 5, 366), true);
  expect(candidate([10, 11, 12], 4, 366), false);
  expect(candidate([], 1, 366), false);
  expect(candidate([5], 0, 366), true);
  expect(candidate([10, 10, 11, 11, 12], 3, 366), true);
  expect(candidate([0, 1, 400, -5], 2, 366), true);
  expect(candidate([6, 0, 1, 2], 4, 7), true);
  expect(candidate([1, 3, 5], 1, 366), true);
}

