Map<String, int> countQrModules(List<String> grid, int r, int c, int size) {
  if (size == 1) {
    String m = grid[r][c];
    return {'B': m == 'B' ? 1 : 0, 'W': m == 'W' ? 1 : 0};
  }
  int h = size ~/ 2;
  Map<String, int> m1 = countQrModules(grid, r, c, h);
  Map<String, int> m2 = countQrModules(grid, r, c + h, h);
  Map<String, int> m3 = countQrModules(grid, r + h, c, h);
  Map<String, int> m4 = countQrModules(grid, r + h, c + h, h);
  return {
    'B': (m1['B'] ?? 0) + (m2['B'] ?? 0) + (m3['B'] ?? 0) + (m4['B'] ?? 0),
    'W': (m1['W'] ?? 0) + (m2['W'] ?? 0) + (m3['W'] ?? 0) + (m4['W'] ?? 0),
  };
}

@pragma('vm:entry-point')
void main() {
  assert(countQrModules(['B'], 0, 0, 1).toString() == '{B: 1, W: 0}');
  assert(countQrModules(['BW', 'WB'], 0, 0, 2).toString() == '{B: 2, W: 2}');
  print('All tests passed!');
}

