@pragma('vm:entry-point')
Set<int> getRecordedTideHeights(List<String> operations) {
  int currentHeight = 0;
  List<int> stack = [];
  Set<int> recorded = {};

  for (String op in operations) {
    if (op == 'SAVE') {
      stack.add(currentHeight);
    } else if (op == 'UNDO') {
      if (stack.isNotEmpty) {
        currentHeight = stack.removeLast();
      }
    } else if (op == 'MARK') {
      recorded.add(currentHeight);
    } else if (op.startsWith('UP ')) {
      currentHeight += int.parse(op.substring(3));
    } else if (op.startsWith('DOWN ')) {
      currentHeight -= int.parse(op.substring(5));
    }
  }

  return recorded;
}

@pragma('vm:entry-point')
void main() {
  assert(getRecordedTideHeights([]).length == 0);
  assert(getRecordedTideHeights(['UP 10', 'MARK']).length == 1);
  assert(getRecordedTideHeights(['UP 10', 'SAVE', 'DOWN 5', 'MARK', 'UNDO', 'MARK']).length == 2);
  print('All tests passed!');
}

tests:
