  final candidate = getRecordedTideHeights;

  expect(candidate([]).length, 0);
  expect(candidate(['MARK']).contains(0), true);
  expect(candidate(['UP 10', 'MARK']).contains(10), true);
  expect(candidate(['UP 10', 'SAVE', 'DOWN 5', 'MARK', 'UNDO', 'MARK']).length, 2);
  expect(candidate(['UP 10', 'SAVE', 'DOWN 5', 'MARK', 'UNDO', 'MARK']).contains(5), true);
  expect(candidate(['DOWN 3', 'MARK', 'DOWN 2', 'MARK', 'UP 5', 'MARK']).length, 3);
  expect(candidate(['SAVE', 'UNDO', 'UNDO', 'MARK']).contains(0), true);
  expect(candidate(['UP 10', 'MARK', 'MARK', 'MARK']).length, 1);
}

