  final candidate = calculateMaxElevatorShaftLoad;

  expect(candidate([[1, 0, 1]]), 1.25);
  expect(candidate([[4, 4, 4], [4, 4, 4]]), 16.0);
  expect(candidate([]), 0.0);
  expect(candidate([[]]), 0.0);
