@pragma('vm:entry-point')
double spellEditRegionUnionArea(List<List<int>> edits) {
  if (edits.isEmpty) return 0.0;

  // Collect all unique x-coordinate boundaries for sweep line
  Set<int> xSet = {};
  for (var rect in edits) {
    xSet.add(rect[0]);
    xSet.add(rect[2]);
  }
  List<int> xs = xSet.toList()..sort();

  double totalArea = 0.0;

  // Sweep across x: for each vertical strip, merge active y-intervals
  for (int i = 0; i < xs.length - 1; i++) {
    int x1 = xs[i];
    int x2 = xs[i + 1];
    int width = x2 - x1;

    // Gather y-intervals of rectangles spanning this x-strip
    List<List<int>> active = [];
    for (var rect in edits) {
      if (rect[0] <= x1 && rect[2] >= x2) {
        active.add([rect[1], rect[3]]);
      }
    }

    if (active.isEmpty) continue;

    // Merge overlapping y-intervals (sweep line on y-axis)
    active.sort((a, b) => a[0].compareTo(b[0]));
    int totalY = 0;
    int curStart = active[0][0];
    int curEnd = active[0][1];

    for (int j = 1; j < active.length; j++) {
      if (active[j][0] > curEnd) {
        totalY += curEnd - curStart;
        curStart = active[j][0];
        curEnd = active[j][1];
      } else {
        if (active[j][1] > curEnd) {
          curEnd = active[j][1];
        }
      }
    }
    totalY += curEnd - curStart;

    totalArea += (width * totalY).toDouble();
  }

  return totalArea;
}

