bool allPrimeRounds(List<List<int>> rounds) {
  for (var round in rounds) {
    int s = round[0] + round[1];
    if (s < 2) return false;
    bool prime = true;
    for (int d = 2; d * d <= s; d++) {
      if (s % d == 0) {
        prime = false;
        break;
      }
    }
    if (!prime) return false;
  }
  return true;
}

