int netDelayMinutes(List<int> log) {
  List<int> stack = [];
  for (int entry in log) {
    if (entry == 0) {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else {
      stack.add(entry);
    }
  }
  return stack.fold(0, (sum, e) => sum + e);
}

