int diceRoundCollapseScore(List<List<int>> rounds) {
  int totalScore = 0;
  for (int r = 0; r < rounds.length; r++) {
    List<int> dice = rounds[r];
    List<bool> paired = List<bool>.filled(dice.length, false);
    for (int i = 0; i < dice.length; i++) {
      if (paired[i]) continue;
      int complement = 7 - dice[i];
      for (int j = i + 1; j < dice.length; j++) {
        if (!paired[j] && dice[j] == complement) {
          paired[i] = true;
          paired[j] = true;
          break;
        }
      }
    }
    for (int i = 0; i < dice.length; i++) {
      if (!paired[i]) {
        totalScore += dice[i];
      }
    }
  }
  return totalScore;
}

