int maxBatches(List<int> available, List<int> needed) {
  if (available.isEmpty) return 0;
  if (available.length == 1) {
    return available[0] ~/ needed[0];
  }
  int mid = available.length ~/ 2;
  int left = maxBatches(available.sublist(0, mid), needed.sublist(0, mid));
  int right = maxBatches(available.sublist(mid), needed.sublist(mid));
  return left < right ? left : right;
}

