Map<String, int> scanCardsBySuit(String notation) {
  const ranks = {'2','3','4','5','6','7','8','9','T','J','Q','K','A'};
  const suits = {'H': 'Hearts', 'S': 'Spades', 'D': 'Diamonds', 'C': 'Clubs'};
  int state = 0; // 0: need rank, 1: need suit
  String pendingSuit = '';
  final counts = <String, int>{'Hearts': 0, 'Spades': 0, 'Diamonds': 0, 'Clubs': 0};
  for (int i = 0; i < notation.length; i++) {
    final ch = notation[i].toUpperCase();
    if (state == 0) {
      if (ranks.contains(ch)) state = 1;
    } else {
      if (suits.containsKey(ch)) {
        counts[suits[ch]!] = counts[suits[ch]!]! + 1;
      }
      state = 0;
    }
  }
  return counts;
}

