int decodeRgbChecksum(String encoded) {
  int sum = 0;
  for (int i = 0; i < encoded.length; i += 2) {
    int count = int.parse(encoded[i]);
    int weight = encoded[i + 1] == 'R' ? 1 : (encoded[i + 1] == 'G' ? 2 : 3);
