@pragma('vm:entry-point')
int cardBracketScore(List<String> plays) {
  List<String> bracketStack = [];
  List<int> undoStack = [];
  List<int> redoStack = [];
  int score = 0;

  int cardValue(String s) {
    switch (s) {
      case "A": return 1;
      case "T": return 10;
      case "J": return 11;
      case "Q": return 12;
      case "K": return 13;
      default: return int.parse(s);
    }
  }

  for (String play in plays) {
    if (play == "(" || play == "[" || play == "{") {
      bracketStack.add(play);
      redoStack.clear();
    } else if (play == ")" || play == "]" || play == "}") {
      if (bracketStack.isEmpty) return -1;
      String opener = bracketStack.removeLast();
      bool match = (play == ")" && opener == "(") ||
                   (play == "]" && opener == "[") ||
                   (play == "}" && opener == "{");
      if (!match) return -1;
      redoStack.clear();
    } else if (play == "U") {
      if (undoStack.isEmpty) return -1;
      int undone = undoStack.removeLast();
      score -= undone;
      redoStack.add(undone);
    } else if (play == "R") {
      if (redoStack.isEmpty) return -1;
      int redone = redoStack.removeLast();
      score += redone;
      undoStack.add(redone);
    } else if (play == "D") {
      if (undoStack.isEmpty) return -1;
      int lastContrib = undoStack.last;
      score += lastContrib;
      undoStack.add(lastContrib);
      redoStack.clear();
    } else {
      int value = cardValue(play);
      int contribution = value * (bracketStack.length + 1);
      score += contribution;
      undoStack.add(contribution);
      redoStack.clear();
    }
  }

  if (bracketStack.isNotEmpty) return -1;
  return score;
}

@pragma('vm:entry-point')
void main() {
  assert(cardBracketScore([]) == 0);
  assert(cardBracketScore(["3", "5"]) == 8);
  assert(cardBracketScore(["(", "]"]) == -1);
  print('All tests passed!');
}

tests:
