  expect(candidate(["(", "K", "D", "U", "Q", ")"]), 50);
  expect(candidate(["3", "U", "R"]), 3);
  expect(candidate(["3", "U", "D"]), -1);
  expect(candidate(["(", "]"]), -1);
  expect(candidate(["(", "3"]), -1);
