List<int> findDuplicateSensorReadings(List<int> readings) {
  Map<int, int> freq = {};
  for (var r in readings) {
    freq[r] = (freq[r] ?? 0) + 1;
  }
  List<int> duplicates = freq.keys.where((k) => freq[k]! > 1).toList();
  duplicates.sort();
  return duplicates;
}

