bool hasTideSurge(List<double> readings, double minRise) {
  if (readings.length < 3) return false;
  List<double> diffs = [];
  for (int i = 1; i < readings.length; i++) {
    diffs.add(readings[i] - readings[i - 1]);
  }
  int consecutive = 0;
  for (double d in diffs) {
    if (d >= minRise) {
      consecutive++;
      if (consecutive >= 3) return true;
    } else {
      consecutive = 0;
    }
  }
  return false;
}

