List<int> chessRowWindowSums(List<int> squares, int k) {
  if (k <= 0 || k > squares.length || squares.isEmpty) {
    return [];
  }
  List<int> result = [];
  int windowSum = 0;
  for (int i = 0; i < squares.length; i++) {
    windowSum += squares[i];
    if (i >= k) {
      windowSum -= squares[i - k];
    }
    if (i >= k - 1) {
      result.add(windowSum);
    }
  }
  return result;
}

