double voteShareForA(String tally) {
  if (tally.isEmpty) return 0.0;
  int aVotes = 0;
  int totalVotes = 0;
  List<String> entries = tally.split(',');
  for (String entry in entries) {
    List<String> parts = entry.split(':');
    int count = int.parse(parts[1]);
    totalVotes += count;
    if (parts[0] == 'A') aVotes += count;
  }
  if (totalVotes == 0) return 0.0;
  return aVotes / totalVotes;
}

