@pragma('vm:entry-point')
int serverLogChecksum(String encoded) {
  const int mod = 9973;
  int checksum = 0;
  int pos = 0;
  int i = 0;

  while (i < encoded.length) {
    int code = encoded.codeUnitAt(i);

    if (code == 33) {
      // '!' is escape: next char is literal
      if (i + 1 < encoded.length) {
        int litCode = encoded.codeUnitAt(i + 1);
        checksum = (checksum + litCode * (pos + 1)) % mod;
        pos++;
        i += 2;
      } else {
        // Trailing '!' is literal
        checksum = (checksum + 33 * (pos + 1)) % mod;
        pos++;
        i++;
      }
    } else if (code >= 65 && code <= 90) {
      // Uppercase A-Z: check if next char is a digit for RLE
      if (i + 1 < encoded.length) {
        int nextCode = encoded.codeUnitAt(i + 1);
        if (nextCode >= 48 && nextCode <= 57) {
          int count = nextCode - 48;
          for (int j = 0; j < count; j++) {
            checksum = (checksum + code * (pos + 1)) % mod;
            pos++;
          }
          i += 2;
        } else {
          checksum = (checksum + code * (pos + 1)) % mod;
          pos++;
          i++;
        }
      } else {
        checksum = (checksum + code * (pos + 1)) % mod;
        pos++;
        i++;
      }
    } else {
      // Literal character
      checksum = (checksum + code * (pos + 1)) % mod;
      pos++;
      i++;
    }
  }

  return checksum;
}

@pragma('vm:entry-point')
void main() {
  assert(serverLogChecksum('A3B2') == 984);
  assert(serverLogChecksum('') == 0);
  assert(serverLogChecksum('!!') == 33);
  print('All tests passed!');
}

