@pragma('vm:entry-point')
Map<String, int> simulateDiceRoundStateMachine(List<int> rolls) {
  int roundsPlayed = 0;
  int totalScore = 0;
  int busts = 0;
  int doubles = 0;
  int maxRoundScore = 0;

  // States: 0=IDLE, 1=ROLLING, 2=BUSTED, 3=DOUBLED
  int state = 0;
  int score = 0;
  int prevRoll = 0;
  bool roundHasRolls = false;

  void endRound() {
    if (roundHasRolls) {
      roundsPlayed++;
      totalScore += score;
      if (state == 2) busts++;
      if (state == 3) doubles++;
      if (score > maxRoundScore) maxRoundScore = score;
    }
    state = 0;
    score = 0;
    prevRoll = 0;
    roundHasRolls = false;
  }

  for (int roll in rolls) {
    if (roll == 0) {
      endRound();
    } else if (state == 0) {
      roundHasRolls = true;
      if (roll == 1) {
        state = 2;
        score = 0;
      } else {
        state = 1;
        score = roll;
        prevRoll = roll;
      }
    } else if (state == 1) {
      if (roll == 1) {
        state = 2;
        score = 0;
      } else if (roll == prevRoll) {
        state = 3;
        score *= 2;
      } else {
        score += roll;
        prevRoll = roll;
      }
    }
  }
  endRound();

  return {
    "roundsPlayed": roundsPlayed,
    "totalScore": totalScore,
    "busts": busts,
    "doubles": doubles,
    "maxRoundScore": maxRoundScore,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(simulateDiceRoundStateMachine([]).toString() == "{roundsPlayed: 0, totalScore: 0, busts: 0, doubles: 0, maxRoundScore: 0}");
  assert(simulateDiceRoundStateMachine([6, 6, 0])["totalScore"] == 12);
  assert(simulateDiceRoundStateMachine([1, 0, 2, 2, 0])["busts"] == 1);
  print('All tests passed!');
}

