Map<String, int> countNestedInventoryItems(Map<String, Object> container) {
  Map<String, int> result = {};
  for (var entry in container.entries) {
    if (entry.value is int) {
      result[entry.key] = (result[entry.key] ?? 0) + (entry.value as int);
    } else if (entry.value is Map<String, Object>) {
      var nested = countNestedInventoryItems(entry.value as Map<String, Object>);
      for (var nestedEntry in nested.entries) {
        result[nestedEntry.key] = (result[nestedEntry.key] ?? 0) + nestedEntry.value;
      }
    }
  }
  return result;
}

