double barcodeDigitAlternationScore(String digits) {
  int state = -1;
  double score = 0.0;
  for (int i = 0; i < digits.length; i++) {
    int digit = int.parse(digits[i]);
    int newState = digit % 2 == 0 ? 0 : 1;
    if (state != -1 && state != newState) {
      score += 0.5;
    }
    state = newState;
  }
  return score;
}

