@pragma('vm:entry-point')
List<int> computeAsciiRowDominantFrequencyScores(List<String> rows) {
  List<int> scores = [];
  for (String row in rows) {
    Map<String, int> charFreq = {};
    for (int i = 0; i < row.length; i++) {
      String ch = row[i];
      if (ch != ' ') {
        charFreq[ch] = (charFreq[ch] ?? 0) + 1;
      }
    }
    if (charFreq.isEmpty) {
      scores.add(0);
      continue;
    }
    Map<int, int> freqOfFreqs = {};
    for (int freq in charFreq.values) {
      freqOfFreqs[freq] = (freqOfFreqs[freq] ?? 0) + 1;
    }
    int maxCount = 0;
    for (int count in freqOfFreqs.values) {
      if (count > maxCount) maxCount = count;
    }
    int dominantFreq = 0;
    for (MapEntry<int, int> entry in freqOfFreqs.entries) {
      if (entry.value == maxCount && entry.key > dominantFreq) {
        dominantFreq = entry.key;
      }
    }
    scores.add(dominantFreq * maxCount);
  }
  return scores;
}

@pragma('vm:entry-point')
void main() {
  assert(computeAsciiRowDominantFrequencyScores(["|||", "abc"]).toString() == "[3, 3]");
  assert(computeAsciiRowDominantFrequencyScores([]).toString() == "[]");
  assert(computeAsciiRowDominantFrequencyScores(["  "]).toString() == "[0]");
  print('All tests passed!');
}

