double maxComplementaryPairScore(String dna) {
  if (dna.length < 2) return 0.0;
  double prev2 = 0.0;
  double prev1 = 0.0;
  for (int i = 1; i < dna.length; i++) {
    double pairScore = 0.0;
    String a = dna[i - 1];
    String b = dna[i];
    if ((a == 'A' && b == 'T') || (a == 'T' && b == 'A') ||
        (a == 'G' && b == 'C') || (a == 'C' && b == 'G')) {
      pairScore = 0.5;
    }
    double current = prev1 > prev2 + pairScore ? prev1 : prev2 + pairScore;
    prev2 = prev1;
    prev1 = current;
  }
  return prev1;
}

