Set<int> availableSeatDays(int firstSeat, int lastSeat, int firstDay, int lastDay, int totalDays, Set<int> maintenanceDays) {
  Set<int> slots = {};
  for (int seat = firstSeat; seat <= lastSeat; seat++) {
    for (int day = firstDay; day <= lastDay; day++) {
      if (!maintenanceDays.contains(day)) {
        slots.add(seat * totalDays + day);
      }
