Set<int> findOddCountBarcodeModeDigits(List<List<int>> barcodes) {
  Map<int, int> modeCount = {};

  for (var barcode in barcodes) {
    if (barcode.isEmpty) continue;

    Map<int, int> freq = {};
    for (var digit in barcode) {
      freq[digit] = (freq[digit] ?? 0) + 1;
    }

    int maxFreq = 0;
    for (var count in freq.values) {
      if (count > maxFreq) maxFreq = count;
    }

    List<int> modes = [];
    for (var entry in freq.entries) {
      if (entry.value == maxFreq) {
        modes.add(entry.key);
      }
    }

    if (modes.length == 1) {
      int modeDigit = modes[0];
      modeCount[modeDigit] = (modeCount[modeDigit] ?? 0) + 1;
    }
  }

  Set<int> result = {};
  for (var entry in modeCount.entries) {
    if (entry.value % 2 == 1) {
      result.add(entry.key);
    }
  }

  return result;
}

