bool isSuccessfulLogLine(String logLine) {
  for (int i = 0; i <= logLine.length - 3; i++) {
    int prev = i > 0 ? logLine[i - 1].codeUnitAt(0) : 32;
    int next = i + 3 < logLine.length ? logLine[i + 3].codeUnitAt(0) : 32;
    if ((prev >= 48 && prev <= 57) || prev == 46) continue;
    if ((next >= 48 && next <= 57) || next == 46) continue;
    int d0 = logLine[i].codeUnitAt(0) - 48;
    int d1 = logLine[i + 1].codeUnitAt(0) - 48;
    int d2 = logLine[i + 2].codeUnitAt(0) - 48;
    if (d0 >= 0 && d0 <= 9 && d1 >= 0 && d1 <= 9 && d2 >= 0 && d2 <= 9) {
      int code = d0 * 100 + d1 * 10 + d2;
      return code >= 200 && code <= 299;
    }
  }
  return false;
}

