String roundedDollarTotal(List<String> actions) {
  List<int> stack = [];
  for (String action in actions) {
    if (action == "undo") {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(int.parse(action));
    }
  }
  int totalMills = 0;
  for (int m in stack) {
    totalMills += m;
  }
  int totalCents = (totalMills + 5) ~/ 10;
  int dollars = totalCents ~/ 100;
  int cents = totalCents % 100;
  return "\$$dollars.${cents.toString().padLeft(2, '0')}";
}

