  assert(validateCargoSections("[]").toString() == "{valid: 1, max_depth: 1, total_sections: 1}");
  assert(validateCargoSections("").toString() == "{valid: 1, max_depth: 0, total_sections: 0}");
  assert(validateCargoSections("[[").toString() == "{valid: 0, max_depth: 0, total_sections: 0}");
