Map<String, int> scanSeatLayout(String layout) {
  Map<String, int> counts = {};
  int currentCount = 0;
  bool hasNumber = false;
  for (int i = 0; i < layout.length; i++) {
    String char = layout[i];
    int code = char.codeUnitAt(0);
    if (code >= 48 && code <= 57) {
      currentCount = currentCount * 10 + (code - 48);
      hasNumber = true;
    } else {
      counts[char] = (counts[char] ?? 0) + (hasNumber ? currentCount : 1);
      currentCount = 0;
      hasNumber = false;
    }
  }
  return counts;
}

