List<int> thermostatManhattanDistances(List<int> schedulePoints) {
  if (schedulePoints.length < 4) return [];
  List<int> distances = [];
  for (int i = 0; i < schedulePoints.length - 2; i += 2) {
    int dt = (schedulePoints[i + 2] - schedulePoints[i]).abs();
    int dTemp = (schedulePoints[i + 3] - schedulePoints[i + 1]).abs();
    distances.add(dt + dTemp);
  }
  return distances;
}

