@pragma('vm:entry-point')
double computeDiceRoundScore(List<int> rolls) {
  // States: 0 = IDLE, 1 = ACTIVE, 2 = BUST
  int state = 0;
  int roundPoints = 0;
  double total = 0.0;

  for (int roll in rolls) {
    if (state == 2) {
      state = 0; // BUST resolves to IDLE before processing this roll
    }

    if (state == 0) {
      if (roll == 1) {
        state = 2; // bust with zero round points, no penalty
      } else if (roll != 6) {
        roundPoints = roll;
        state = 1; // begin active round
      }
      // roll == 6 in IDLE: nothing to bank, remain IDLE
    } else if (state == 1) {
      if (roll == 1) {
        roundPoints = 0;
        state = 2; // bust: forfeit accumulated round points
      } else if (roll == 6) {
        total += roundPoints * 0.5; // bank half the round points
        roundPoints = 0;
        state = 0; // return to IDLE
      } else {
        roundPoints += roll; // accumulate face value
      }
    }
  }

  return total;
}

