bool isInventorySorted(List<String> names, List<int> rarities, List<double> values, List<double> weights) {
  if (names.length != rarities.length || names.length != values.length || names.length != weights.length) {
    return false;
  }
  for (int i = 0; i < names.length - 1; i++) {
    int cmpRarity = rarities[i + 1].compareTo(rarities[i]);
    if (cmpRarity > 0) return false;
    if (cmpRarity < 0) continue;
    double ratioI = values[i] / weights[i];
    double ratioJ = values[i + 1] / weights[i + 1];
    int cmpRatio = ratioJ.compareTo(ratioI);
    if (cmpRatio > 0) return false;
    if (cmpRatio < 0) continue;
    int cmpName = names[i].compareTo(names[i + 1]);
    if (cmpName > 0) return false;
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isInventorySorted([], [], [], []) == true);
  assert(isInventorySorted(["Sword"], [3], [10.0], [2.0]) == true);
  assert(isInventorySorted(["Sword", "Dagger"], [3, 5], [10.0, 5.0], [2.0, 1.0]) == false);
