@pragma('vm:entry-point')
double maxQuarterRoundedWindowDollars(List<int> cents, int k) {
  if (cents.isEmpty || k <= 0 || k > cents.length) return 0.0;
  int roundToQuarter(int c) => ((c + 12) ~/ 25) * 25;
  int windowSum = 0;
  for (int i = 0; i < k; i++) {
    windowSum += roundToQuarter(cents[i]);
  }
  int maxSum = windowSum;
  for (int i = k; i < cents.length; i++) {
    windowSum += roundToQuarter(cents[i]) - roundToQuarter(cents[i - k]);
    if (windowSum > maxSum) maxSum = windowSum;
  }
  return maxSum / 100.0;
}

