@pragma('vm:entry-point')
List<String> decodeChargeCycleDeltas(String encoded) {
  if (encoded.isEmpty) return [];

  List<String> result = [];
  int i = 0;
  int currentCharge = 0;
  int lastDelta = 0;

  int parseNum() {
    int start = i;
    while (i < encoded.length && encoded[i].codeUnitAt(0) >= 48 && encoded[i].codeUnitAt(0) <= 57) {
      i++;
    }
    return int.parse(encoded.substring(start, i));
  }

  while (i < encoded.length) {
    String ch = encoded[i];
    if (ch == '+' || ch == '-') {
      i++;
      int delta = parseNum();
      if (ch == '-') delta = -delta;
      lastDelta = delta;
      currentCharge += delta;
      result.add('$currentCharge%');
    } else if (ch == '*') {
      i++;
      int count = parseNum();
      for (int j = 0; j < count; j++) {
        currentCharge += lastDelta;
        result.add('$currentCharge%');
      }
    } else {
      currentCharge = parseNum();
      result.add('$currentCharge%');
    }
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeChargeCycleDeltas("").toString() == "[]");
  assert(decodeChargeCycleDeltas("100").toString() == "[100%]");
  assert(decodeChargeCycleDeltas("50+5+5*3-10-10*2").length == 10);
  print('All tests passed!');
}

