List<String> formatTrainSchedule(List<List<int>> timetable) {
  List<String> result = [];
  for (List<int> route in timetable) {
    List<String> times = [];
    for (int minutes in route) {
      int hours = minutes ~/ 60;
      int mins = minutes % 60;
      times.add('${hours.toString().padLeft(2, '0')}:${mins.toString().padLeft(2, '0')}');
    }
    result.add(times.join('-'));
  }
  return result;
}

