@pragma('vm:entry-point')
List<int> shelfCodeRange(List<int> sortedCodes, int target) {
  int first = -1;
  int last = -1;
  int lo = 0;
  int hi = sortedCodes.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (sortedCodes[mid] < target) {
      lo = mid + 1;
    } else if (sortedCodes[mid] > target) {
      hi = mid - 1;
    } else {
      first = mid;
      hi = mid - 1;
    }
  }
  lo = 0;
  hi = sortedCodes.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (sortedCodes[mid] < target) {
      lo = mid + 1;
    } else if (sortedCodes[mid] > target) {
      hi = mid - 1;
    } else {
      last = mid;
      lo = mid + 1;
    }
  }
  return [first, last];
}

@pragma('vm:entry-point')
void main() {
  assert(shelfCodeRange([1, 2, 3, 4, 5], 3).first == 2);
  assert(shelfCodeRange([1, 2, 2, 2, 3, 4], 2).last == 3);
