bool isPrimeLogChecksum(int lineNumber) {
  if (lineNumber < 0) return false;
  int sum = 0;
  int n = lineNumber;
  while (n > 0) {
    sum += n % 10;
    n ~/= 10;
  }
  if (sum < 2) return false;
  if (sum < 4) return true;
  if (sum % 2 == 0) return false;
  for (int i = 3; i * i <= sum; i += 2) {
    if (sum % i == 0) return false;
  }
  return true;
}

