double averageShelfSpacing(List<double> positions) {
  if (positions.length < 2) return 0.0;
  final sorted = [...positions]..sort();
  final gaps = <double>[];
  for (int i = 1; i < sorted.length; i++) {
    gaps.add(sorted[i] - sorted[i - 1]);
