@pragma('vm:entry-point')
Map<String, int> aggregateLootDrops(String lootLog) {
  Map<String, int> tally = {};
  if (lootLog.isEmpty) return tally;
  for (String entry in lootLog.split(',')) {
    entry = entry.trim();
    if (entry.isEmpty) continue;
    List<String> parts = entry.split(':');
    if (parts.length != 2) continue;
    String item = parts[0].trim();
    int count = int.tryParse(parts[1].trim()) ?? 0;
    if (item.isEmpty) continue;
    tally[item] = (tally[item] ?? 0) + count;
  }
  return tally;
}

@pragma('vm:entry-point')
