    if (g >= threshold) bandCounts['highGreen'] = bandCounts['highGreen']! + 1;
    if (b < threshold) bandCounts['lowBlue'] = bandCounts['lowBlue']! + 1;
    if (b >= threshold) bandCounts['highBlue'] = bandCounts['highBlue']! + 1;
