@pragma('vm:entry-point')
List<String> tokenizeDnaCodons(String dna) {
  const stop = {'TAA', 'TAG', 'TGA'};
  final r = <String>[];
  for (var i = 0; i < dna.length; i += 3) {
    if (i + 3 > dna.length) { r.add('TRUNCATED:${dna.substring(i)}'); break; }
    final c = dna.substring(i, i + 3);
    if (!RegExp(r'^[ACGT]{3}$').hasMatch(c)) r.add('INVALID:$c');
    else if (c == 'ATG') r.add('START');
    else if (stop.contains(c)) r.add('STOP');
    else r.add('CODON:$c');
  }
  return r;
}

@pragma('vm:entry-point')
void main() {
  assert(tokenizeDnaCodons("ATG").length == 1);
  assert(tokenizeDnaCodons("").toString() == "[]");
  assert(tokenizeDnaCodons("ATGTAA").toString() == "[START, STOP]");
  print('All tests passed!');
}

