Set<int> topRatedTrackSlots(List<List<int>> playlistRatings, int minAverage) {
  if (playlistRatings.isEmpty || playlistRatings[0].isEmpty) return {};
  int numColumns = playlistRatings[0].length;
  int numRows = playlistRatings.length;
  Set<int> result = {};
  for (int col = 0; col < numColumns; col++) {
    int sum = 0;
    for (int row = 0; row < numRows; row++) {
      sum += playlistRatings[row][col];
    }
    double avg = sum / numRows;
    if (avg > minAverage) result.add(col);
  }
  return result;
}

