Set<int> largestFittingQrVersion(int maxPixelWidth, int modulePixelSize) {
  int maxDimension = maxPixelWidth ~/ modulePixelSize;
  int lo = 1, hi = 40, result = 0;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (4 * mid + 17 <= maxDimension) {
      result = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return result == 0 ? <int>{} : {result};
}

