@pragma('vm:entry-point')
List<int> rleLogStatusCodes(String logText) {
  List<int> result = [];
  List<String> lines = logText
      .split('\n')
      .where((l) => l.trim().isNotEmpty)
      .toList();
  int? prevCode;
  int count = 0;
  for (String line in lines) {
    int bracketEnd = line.indexOf(']');
    if (bracketEnd < 0) continue;
    String afterBracket = line.substring(bracketEnd + 1).trimLeft();
    int code = 0;
    bool valid = afterBracket.length >= 3;
    for (int i = 0; valid && i < 3; i++) {
      int c = afterBracket.codeUnitAt(i);
      if (c < 0x30 || c > 0x39) {
        valid = false;
        break;
      }
      code = code * 10 + (c - 0x30);
    }
    if (!valid) continue;
    if (code == prevCode) {
      count++;
    } else {
      if (prevCode != null) {
        result.add(count);
        result.add(prevCode);
      }
      prevCode = code;
      count = 1;
    }
  }
  if (prevCode != null) {
    result.add(count);
    result.add(prevCode);
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(rleLogStatusCodes("").length == 0);
  assert(rleLogStatusCodes("[t] 200 /api").toString() == "[1, 200]");
  assert(rleLogStatusCodes("[a] 200 /x\n[b] 404 /y\n[c] 404 /z").toString() == "[1, 200, 2, 404]");
  print('All tests passed!');
}

