@pragma('vm:entry-point')
bool validateBarcodeStrips(List<int> digits, List<String> bracketTypes) {
  if (digits.length != bracketTypes.length || digits.isEmpty) return false;
  final stack = <int>[];
  for (var i = 0; i < digits.length; i++) {
    if (digits[i] < 0 || digits[i] > 9) return false;
    if (bracketTypes[i] == 'open') {
      stack.add(digits[i]);
    } else if (bracketTypes[i] == 'close') {
      if (stack.isEmpty) return false;
      final last = stack.removeLast();
      if ((last + digits[i]) % 10 != 0) return false;
    } else {
      return false;
    }
  }
  return stack.isEmpty;
}

@pragma('vm:entry-point')
void main() {
  assert(validateBarcodeStrips([1, 2, 3], ['open', 'close', 'open']) == false);
  assert(validateBarcodeStrips([1, 9, 2, 8], ['open', 'close', 'open', 'close']) == true);
  assert(validateBarcodeStrips([5], ['open']) == false);
  print('All tests passed!');
}

