@pragma('vm:entry-point')
Set<int> findOveractiveAnomalySensorIds(List<int> samples, int minOccurrences, int readingThreshold) {
  Map<int, int> counts = {};
  Map<int, int> sums = {};
  for (int sample in samples) {
    int sensorId = sample ~/ 1000;
    int reading = sample % 1000;
    counts.update(sensorId, (v) => v + 1, ifAbsent: () => 1);
    sums.update(sensorId, (v) => v + reading, ifAbsent: () => reading);
  }
  Set<int> anomalies = {};
  counts.forEach((sensorId, count) {
    if (count >= minOccurrences && sums[sensorId]! > readingThreshold * count) {
      anomalies.add(sensorId);
    }
  });
  return anomalies;
}

