@pragma('vm:entry-point')
Set<int> simulateZoneDispatch(List<String> log) {
  final zoneA = <int>[];
  final zoneB = <int>[];
  final dispatched = <int>{};
  for (final entry in log) {
    if (entry.startsWith('load A:')) {
      zoneA.add(int.parse(entry.substring(7)));
    } else if (entry.startsWith('load B:')) {
      zoneB.add(int.parse(entry.substring(7)));
    } else if (entry == 'dispatch A') {
      if (zoneA.isNotEmpty) dispatched.add(zoneA.removeLast());
    } else if (entry == 'dispatch B') {
      if (zoneB.isNotEmpty) dispatched.add(zoneB.removeLast());
    } else if (entry == 'dispatch any') {
      if (zoneA.isNotEmpty) {
        dispatched.add(zoneA.removeLast());
      } else if (zoneB.isNotEmpty) {
        dispatched.add(zoneB.removeLast());
      }
    }
  }
  return dispatched;
}

@pragma('vm:entry-point')
void main() {
  assert(simulateZoneDispatch(<String>[]).isEmpty);
  assert(simulateZoneDispatch(['load A:5', 'dispatch A']).length == 1);
  assert(simulateZoneDispatch(['load A:5', 'dispatch A']).contains(5));
  print('All tests passed!');
}

