@pragma('vm:entry-point')
int timetableManhattanLength(List<int> stations, List<int> minutes) {
  // Computes the total Manhattan distance between consecutive stops
  // in the station-time plane for a train timetable.
  int n = stations.length;
  if (n != minutes.length) {
    throw ArgumentError('Stations and minutes must have the same length');
  }
  int total = 0;
  for (int i = 1; i < n; i++) {
    int dx = (stations[i] - stations[i - 1]).abs();
    int dy = (minutes[i] - minutes[i - 1]).abs();
    total += dx + dy;
  }
  return total;
}

