@pragma('vm:entry-point')
Set<int> chargeLogSurvivors(List<int> cycles) {
  List<int> undoStack = <int>[];
  int stored = 0;
  for (int i = 0; i < cycles.length; i++) {
    stored += cycles[i];
    undoStack.add(i);
    while (stored < 0 && undoStack.isNotEmpty) {
      int popped = undoStack.removeLast();
      stored -= cycles[popped];
    }
  }
  return undoStack.toSet();
}

@pragma('vm:entry-point')
