List<int> collectServerErrorIndices(List<String> logs) {
  List<int> helper(List<String> sub, int off) {
    if (sub.isEmpty) return [];
    if (sub.length == 1) return sub[0].contains('ERROR') ? [off] : [];
    var mid = sub.length ~/ 2;
    var left = helper(sub.sublist(0, mid), off);
    var right = helper(sub.sublist(mid), off + mid);
    return [...left, ...right];
  }
  return helper(logs, 0);
}

