Set<int> extractContinuousPassIds(List<List<int>> visibilityGrid, int minLength) {
  if (minLength <= 0) return {};
  final result = <int>{};
  for (int r = 0; r < visibilityGrid.length; r++) {
    final row = visibilityGrid[r];
    if (row.isEmpty) continue;
    int currentId = row[0];
    int run = 1;
    for (int c = 1; c < row.length; c++) {
      if (row[c] == currentId && currentId > 0) {
        run++;
      } else {
        if (run >= minLength && currentId > 0) result.add(currentId);
        currentId = row[c];
        run = 1;
      }
    }
    if (run >= minLength && currentId > 0) result.add(currentId);
  }
  return result;
}

