@pragma('vm:entry-point')
double calculateOrderedSeatSpacing(List<double> seatPositions) {
  if (seatPositions.length < 2) return 0.0;
  List<double> sorted = List.from(seatPositions);
  sorted.sort((a, b) {
    double distA = (a - 0.0).abs();
    double distB = (b - 0.0).abs();
    if (distA != distB) return distA.compareTo(distB);
    return a.compareTo(b);
  });
  double sum = 0.0;
  for (int i = 1; i < sorted.length; i++) {
    sum += (sorted[i] - sorted[i - 1]).abs();
  }
  return sum / (sorted.length - 1);
}

