@pragma('vm:entry-point')
Map<String, int> computePacketIntervalSummary(List<int> arrivalDays, List<int> packetSizes) {
  if (arrivalDays.isEmpty) {
    return {'totalSize': 0, 'daySpan': 0, 'numIntervals': 0};
  }
  int totalSize = 0;
  List<int> days = List.from(arrivalDays);
  for (int s in packetSizes) {
    totalSize += s;
  }
  List<int> sortedDays = List.from(days)..sort();
  int minDay = sortedDays.first;
  int maxDay = sortedDays.last;
  int daySpan = maxDay - minDay + 1;
  int numIntervals = 1;
  for (int i = 1; i < sortedDays.length; i++) {
    if (sortedDays[i] > sortedDays[i - 1] + 1) {
      numIntervals++;
    }
  }
  return {'totalSize': totalSize, 'daySpan': daySpan, 'numIntervals': numIntervals};
}

