bool shelvesConflictInWarehouse(int x1, int y1, int w1, int h1, int x2, int y2, int w2, int h2) {
  int right1 = x1 + w1;
  int right2 = x2 + w2;
  int top1 = y1 + h1;
  int top2 = y2 + h2;
  bool xOverlap = false;
  if (x1 < right2) {
    if (x2 < right1) {
      xOverlap = true;
    }
  }
  bool yOverlap = false;
  if (y1 < top2) {
    if (y2 < top1) {
      yOverlap = true;
    }
  }
  if (xOverlap) {
    if (yOverlap) {
      return true;
    }
  }
  if (w1 <= 0 || h1 <= 0 || w2 <= 0 || h2 <= 0) {
    return false;
  }
  return false;
}

