List<int> calculateDominantSatellitePerWindow(List<int> satellitePasses, int windowSize) {
  if (windowSize <= 0 || satellitePasses.isEmpty || windowSize > satellitePasses.length) {
    return [];
  }
  List<int> result = [];
  int n = satellitePasses.length;
  for (int i = 0; i <= n - windowSize; i++) {
    Map<int, int> freq = {};
    for (int j = i; j < i + windowSize; j++) {
      int sat = satellitePasses[j];
      freq[sat] = (freq[sat] ?? 0) + 1;
    }
    int maxFreq = 0;
    int dominant = 2147483647;
    freq.forEach((sat, f) {
      if (f > maxFreq || (f == maxFreq && sat < dominant)) {
        maxFreq = f;
        dominant = sat;
      }
    });
    result.add(dominant);
  }
  return result;
}

