bool hasSymmetricEmptyBlock(List<int> theaterRow, int blockSize) {
  if (blockSize < 2 || blockSize % 2 != 0 || theaterRow.length < blockSize) return false;
  int left = 0;
  int right = blockSize - 1;
  while (right < theaterRow.length) {
    bool isValid = true;
    int half = blockSize ~/ 2;
    int mid = left + half - 1;
    for (int i = 0; i < half; i++) {
      if (theaterRow[left + i] != 0 || theaterRow[right - i] != 0) {
        isValid = false;
        break;
      }
    }
    if (isValid) {
      for (int i = 0; i < half ~/ 2; i++) {
        if (theaterRow[mid - i] != theaterRow[mid + 1 + i]) {
          isValid = false;
          break;
        }
      }
    }
    if (isValid) return true;
    left++;
    right++;
  }
  return false;
}

