@pragma('vm:entry-point')
int scanTheaterSeatingTransitions(List<String> chart) {
  if (chart.isEmpty) return 0;
  int total = 0;
  for (int r = 0; r < chart.length; r++) {
    String row = chart[r];
    int state = 0;
    int consecutive = 0;
    int blockCount = 0;
    bool prevWasEdge = false;
    for (int i = 0; i < row.length; i++) {
      String ch = row[i];
      if (state == 0) {
        if (ch == '.') {
          state = 1;
          consecutive = 1;
        } else if (ch == 'X') {
          state = 2;
          if (prevWasEdge) total += 1;
          prevWasEdge = true;
        } else {
          state = 3;
        }
      } else if (state == 1) {
        if (ch == '.') {
          consecutive++;
          if (consecutive >= 3) blockCount++;
        } else if (ch == 'X') {
          if (consecutive >= 2) total += blockCount + 1;
          state = 2;
          consecutive = 0;
          blockCount = 0;
          prevWasEdge = true;
        } else {
          state = 3;
          total += consecutive ~/ 2;
        }
      } else if (state == 2) {
        if (ch == '.') {
          state = 1;
          consecutive = 1;
          prevWasEdge = false;
        } else if (ch == 'X') {
          prevWasEdge = true;
        } else {
          state = 3;
        }
      } else {
        if (ch == 'X' || ch == '.') state = (ch == '.') ? 1 : 2;
      }
    }
    if (state == 1 && consecutive >= 2) total += (blockCount > 0) ? blockCount + 1 : 1;
    if (r > 0 && chart[r-1].length == row.length && state == 2) total += 2;
  }
  return total;
}

