List<String> groupByDominantChannel(List<String> pixels) {
  Map<String, int> counts = {};
  for (String pixel in pixels) {
    List<String> parts = pixel.split(',');
    if (parts.length != 3) continue;
    int r = int.tryParse(parts[0]) ?? -1;
    int g = int.tryParse(parts[1]) ?? -1;
    int b = int.tryParse(parts[2]) ?? -1;
    if (r < 0 || g < 0 || b < 0) continue;
    String dom;
    if (r >= g && r >= b) {
      dom = 'R';
    } else if (g >= b) {
      dom = 'G';
    } else {
      dom = 'B';
    }
    counts[dom] = (counts[dom] ?? 0) + 1;
  }
  List<String> result = counts.entries
      .map((e) => '${e.key}:${e.value}')
      .toList();
  result.sort();
  return result;
}

