bool hasUniqueAndBalancedSeating(List<List<int>> seatingChart) {
  if (seatingChart.isEmpty) return true;
  var flattened = seatingChart.expand((row) => row).toList();
  var occupied = flattened.where((id) => id != 0).toList();
  if (occupied.length != occupied.toSet().length) return false;
  var target = seatingChart[0].where((id) => id != 0).length;
  for (var row in seatingChart.skip(1)) {
    if (row.where((id) => id != 0).length != target) return false;
  }
  return true;
}

