@pragma('vm:entry-point')
int calculateDnaPathSharedManhattanArea(String seq1, String seq2) {
  Map<String, int> dx = {'A': 0, 'T': 0, 'C': 1, 'G': -1};
  Map<String, int> dy = {'A': 1, 'T': -1, 'C': 0, 'G': 0};
  List<int> x1 = [0], y1 = [0];
  for (int i = 0; i < seq1.length; i++) {
    String b = seq1[i];
    if (!dx.containsKey(b)) continue;
    x1.add(x1.last + dx[b]!);
    y1.add(y1.last + dy[b]!);
  }
  List<int> x2 = [0], y2 = [0];
  for (int i = 0; i < seq2.length; i++) {
    String b = seq2[i];
    if (!dx.containsKey(b)) continue;
    x2.add(x2.last + dx[b]!);
    y2.add(y2.last + dy[b]!);
  }
  int minX = 2147483647, maxX = -2147483648, minY = 2147483647, maxY = -2147483648;
  Set<String> points2 = {};
  for (int i = 0; i < x2.length; i++) {
    points2.add('${x2[i]},${y2[i]}');
  }
  bool first = true;
  for (int i = 0; i < x1.length; i++) {
    String key = '${x1[i]},${y1[i]}';
    if (points2.contains(key)) {
      if (first) {
        minX = maxX = x1[i];
        minY = maxY = y1[i];
        first = false;
      } else {
        if (x1[i] < minX) minX = x1[i];
        if (x1[i] > maxX) maxX = x1[i];
        if (y1[i] < minY) minY = y1[i];
        if (y1[i] > maxY) maxY = y1[i];
      }
    }
  }
  if (first) return 0;
  int width = maxX - minX;
  int height = maxY - minY;
  return width * height;
}

