@pragma('vm:entry-point')
bool matchesWithSingleSpellEditAfterRle(String rle1, String rle2) {
  String decodeRLE(String s) {
    if (s.isEmpty) return '';
    StringBuffer out = StringBuffer();
    int i = 0;
    while (i < s.length) {
      String ch = s[i];
      if (!RegExp(r'[a-z]').hasMatch(ch)) return '';
      i++;
      if (i >= s.length || !RegExp(r'[0-9]').hasMatch(s[i])) return '';
      int num = 0;
      while (i < s.length && RegExp(r'[0-9]').hasMatch(s[i])) {
        num = num * 10 + (s.codeUnitAt(i) - 48);
        i++;
      }
      if (num == 0) return '';
      out.write(ch * num);
    }
    return out.toString();
  }
  int levenshtein(String s, String t) {
    int n = s.length, m = t.length;
    List<List<int>> dp = List.generate(n + 1, (_) => List.filled(m + 1, 0));
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        int cost = s[i - 1] == t[j - 1] ? 0 : 1;
        dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((a, b) => a < b ? a : b);
      }
    }
    return dp[n][m];
  }
  String d1 = decodeRLE(rle1);
  String d2 = decodeRLE(rle2);
  return levenshtein(d1, d2) == 1;
}

