bool validateBarcodeDigitGroups(String barcode) {
  int i = 0;
  while (i < barcode.length) {
    if (barcode.codeUnitAt(i) < 48 || barcode.codeUnitAt(i) > 57) {
      i++;
      continue;
    }
    int start = i;
    int sum = 0;
    while (i < barcode.length && barcode.codeUnitAt(i) >= 48 && barcode.codeUnitAt(i) <= 57) {
      sum += barcode.codeUnitAt(i) - 48;
      i++;
    }
    int len = i - start;
    if (len % 2 == 1) {
      if (sum % 2 != 0) return false;
    } else {
      if (sum % 3 != 0) return false;
    }
  }
  return true;
}

