String summarizeMazeCellFrequencies(List<String> grid) {
  Map<String, int> freq = {};
  for (String row in grid) {
    for (int j = 0; j < row.length; j++) {
      String cell = row[j];
      freq[cell] = (freq[cell] ?? 0) + 1;
    }
  }
  List<String> keys = freq.keys.toList()..sort();
  List<String> parts = [];
  for (String k in keys) {
    parts.add('$k:${freq[k]}');
