@pragma('vm:entry-point')
String resolveMazePathUndos(List<String> commands) {
  List<List<int>> path = [
    [0, 0]
  ];
  Map<String, List<int>> deltas = {
    'N': [0, 1],
    'S': [0, -1],
    'E': [1, 0],
    'W': [-1, 0]
  };
  for (String cmd in commands) {
    if (cmd == 'undo') {
      if (path.length > 1) path.removeLast();
    } else if (deltas.containsKey(cmd)) {
      List<int> last = path.last;
      List<int> d = deltas[cmd]!;
      path.add([last[0] + d[0], last[1] + d[1]]);
    }
  }
  List<int> finalPos = path.last;
  return '${finalPos[0]},${finalPos[1]}';
}

@pragma('vm:entry-point')
