@pragma('vm:entry-point')
List<int> findHighMoistureZones(List<List<int>> grid, int threshold, int minLength) {
  List<int> zoneLengths = [];
  for (int r = 0; r < grid.length; r++) {
    List<int> row = grid[r];
    int n = row.length;
    int left = 0;
    while (left < n) {
      if (row[left] >= threshold) {
        int right = left;
        while (right < n && row[right] >= threshold) {
          right++;
        }
        int length = right - left;
        if (length >= minLength) {
          zoneLengths.add(length);
        }
        left = right;
      } else {
        left++;
      }
    }
  }
  zoneLengths.sort();
  return zoneLengths;
}

@pragma('vm:entry-point')
