bool hasConsecutiveSampleStreak(List<int> sampleDays, int minStreak) {
  if (sampleDays.isEmpty || minStreak <= 0) return false;
  var days = List<int>.from(sampleDays);
  days.sort();
  int currentStreak = 1;
  int maxStreak = 1;
  for (int i = 1; i < days.length; i++) {
    if (days[i] == days[i - 1] + 1) {
      currentStreak++;
      if (currentStreak > maxStreak) maxStreak = currentStreak;
    } else if (days[i] != days[i - 1]) {
      currentStreak = 1;
    }
  }
  return maxStreak >= minStreak;
}

