@pragma('vm:entry-point')
bool hasStableRechargeCycle(List<double> cycleCharges, double stabilityThreshold) {
  if (cycleCharges.length < 3) return false;
  int left = 0;
  int right = cycleCharges.length - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    bool stable = cycleCharges[mid] >= stabilityThreshold;
    if (mid > 0) stable = stable && cycleCharges[mid - 1] <= cycleCharges[mid];
    if (mid < cycleCharges.length - 1) stable = stable && cycleCharges[mid + 1] <= cycleCharges[mid];
    if (stable) return true;
    if (cycleCharges[mid] < stabilityThreshold) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasStableRechargeCycle([0.5, 0.75, 0.6], 0.75) == true);
  assert(hasStableRechargeCycle([0.25, 0.5, 1.0], 0.6) == true);
  assert(hasStableRechargeCycle([0.5, 0.75, 0.6], 0.8) == false);
