@pragma('vm:entry-point')
Set<int> corruptedLogIndices(List<String> lines) {
  // Each valid log line has the form '<payload>#<checksum>' where checksum
  // is (sum of payload code units) mod 97. The '#' used as separator is the
  // LAST '#' in the line, so payloads may themselves contain '#'.
  // Returns the set of indices of corrupted lines (bad/missing checksum).
  final corrupted = <int>{};
  for (var i = 0; i < lines.length; i++) {
    final line = lines[i];
    final sep = line.lastIndexOf('#');
    if (sep < 0) {
      corrupted.add(i);
      continue;
    }
    final payload = line.substring(0, sep);
    final checkStr = line.substring(sep + 1);
    final declared = int.tryParse(checkStr);
    if (checkStr.isEmpty || declared == null) {
      corrupted.add(i);
      continue;
    }
    var sum = 0;
    for (final code in payload.codeUnits) {
      sum += code;
    }
    if (sum % 97 != declared) {
      corrupted.add(i);
    }
  }
  return corrupted;
}

@pragma('vm:entry-point')
void main() {
  assert(corruptedLogIndices(['GET /#12', 'ERROR#6']).isEmpty);
  assert(corruptedLogIndices(['GET /#13']).length == 1);
  assert(corruptedLogIndices(['noChecksum']).contains(0));
  print('All tests passed!');
}

