@pragma('vm:entry-point')
List<int> scoreDiceRounds(List<List<int>> rounds) {
  // For each round of dice rolls, compute a score:
  // - Rolling a 1 wipes the round's score back to 0 (a "bust").
  // - Rolling the same value as the previous roll scores double that value
  //   (a "hot streak" bonus).
  // - Otherwise the roll's face value is added to the score.
  final scores = <int>[];
  for (final round in rounds) {
    var score = 0;
    int? prev;
    for (final roll in round) {
      if (roll == 1) {
        score = 0;
      } else if (prev != null && roll == prev) {
        score += roll * 2;
      } else {
        score += roll;
      }
      prev = roll;
    }
    scores.add(score);
  }
  return scores;
}

@pragma('vm:entry-point')
void main() {
  assert(scoreDiceRounds([[2, 3, 4]]).toString() == '[9]');
