@pragma('vm:entry-point')
int firstSimultaneousTrackStart(int period1, int offset1, int period2, int offset2) {
  // Two playlists loop forever with the given periods (in seconds).
  // A featured track starts at `offset1` seconds into every loop of
  // playlist 1 and at `offset2` seconds into every loop of playlist 2.
  // Return the earliest non-negative second t at which both featured
  // tracks start simultaneously, i.e. t % period1 == offset1 % period1
  // and t % period2 == offset2 % period2, or -1 if it never happens.
  int a = offset1 % period1;
  int b = offset2 % period2;
  // Extended Euclid: find g = gcd(period1, period2) and s with
  // period1 * s == g (mod period2).
  int oldR = period1, r = period2;
  int oldS = 1, s = 0;
  while (r != 0) {
    int q = oldR ~/ r;
    int tmp = oldR - q * r;
    oldR = r;
    r = tmp;
    tmp = oldS - q * s;
    oldS = s;
    s = tmp;
  }
  int g = oldR;
  if ((b - a) % g != 0) return -1;
  int m = period2 ~/ g; // reduced modulus
  int mult = ((b - a) ~/ g) % m;
  int x = (mult * (oldS % m)) % m;
  if (x < 0) x += m;
  int t = a + period1 * x;
  int lcm = period1 ~/ g * period2;
  return t % lcm;
}

@pragma('vm:entry-point')
void main() {
  assert(firstSimultaneousTrackStart(4, 1, 6, 3) == 9);
  assert(firstSimultaneousTrackStart(3, 2, 5, 3) == 8);
  assert(firstSimultaneousTrackStart(4, 0, 6, 1) == -1);
  print('All tests passed!');
}

