List<int> tideStepDistances(List<List<int>> readings) {
  // Each reading is [minute, heightCm]. Returns the Manhattan distance
  // between each consecutive pair of readings on the time/height grid.
  List<int> result = [];
  for (int i = 1; i < readings.length; i++) {
    int dt = (readings[i][0] - readings[i - 1][0]).abs();
    int dh = (readings[i][1] - readings[i - 1][1]).abs();
    result.add(dt + dh);
  }
  return result;
}

