double heatingDegreeMinutes(List<int> switchTimes, List<double> temps, double baseline, int startMinute, int endMinute) {
  // switchTimes[i] is the minute-of-day (0..1439) when temps[i] takes effect.
  // switchTimes is sorted ascending and starts at 0; the last setting lasts
  // until minute 1440. Returns total degree-minutes above baseline within
  // the query interval [startMinute, endMinute).
  if (switchTimes.isEmpty || startMinute >= endMinute) {
    return 0.0;
  }
  double total = 0.0;
  for (int i = 0; i < switchTimes.length; i++) {
    int segStart = switchTimes[i];
    int segEnd = (i + 1 < switchTimes.length) ? switchTimes[i + 1] : 1440;
    int lo = segStart > startMinute ? segStart : startMinute;
    int hi = segEnd < endMinute ? segEnd : endMinute;
    if (hi > lo) {
      double excess = temps[i] - baseline;
      if (excess > 0) {
        total += excess * (hi - lo);
      }
    }
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(heatingDegreeMinutes([0, 360, 1320], [16.0, 21.0, 16.5], 18.0, 300, 600) == 720.0);
  assert(heatingDegreeMinutes([0], [20.5], 18.0, 100, 200) == 250.0);
  assert(heatingDegreeMinutes([], [], 18.0, 0, 1440) == 0.0);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = heatingDegreeMinutes;

  expect(candidate([0, 360, 1320], [16.0, 21.0, 16.5], 18.0, 300, 600), 720.0);
  expect(candidate([0, 360, 1320], [16.0, 21.0, 16.5], 18.0, 0, 1440), 2880.0);
  expect(candidate([], [], 18.0, 0, 1440), 0.0);
  expect(candidate([0], [25.0], 20.0, 600, 600), 0.0);
  expect(candidate([0], [20.5], 18.0, 100, 200), 250.0);
  expect(candidate([0, 720], [17.0, 17.5], 18.0, 0, 1440), 0.0);
  expect(candidate([0, 720], [19.0, 21.5], 19.0, 700, 740), 50.0);
  expect(candidate([0], [20.0], 18.0, 1400, 1500), 80.0);
}

