@pragma('vm:entry-point')
List<int> bracketRoundMatches(int players) {
  // Pads the field up to the next power of two (byes fill empty slots),
  // then returns the number of matches played in each round.
  if (players < 2) return <int>[];
  var size = 1;
  while (size < players) {
    size *= 2;
  }
  final rounds = <int>[];
  while (size > 1) {
    rounds.add(size ~/ 2);
    size ~/= 2;
  }
  return rounds;
}

@pragma('vm:entry-point')
void main() {
  assert(bracketRoundMatches(5).toString() == '[4, 2, 1]');
  assert(bracketRoundMatches(2).toString() == '[1]');
  assert(bracketRoundMatches(1).toString() == '[]');
  print('All tests passed!');
}

