@pragma('vm:entry-point')
double mostPopularRowShare(List<String> bookedSeats) {
  if (bookedSeats.isEmpty) return 0.0;
  final counts = <String, int>{};
  for (final row in bookedSeats) {
    counts[row] = (counts[row] ?? 0) + 1;
  }
  var maxCount = 0;
  for (final c in counts.values) {
    if (c > maxCount) maxCount = c;
  }
  return maxCount / bookedSeats.length;
}

@pragma('vm:entry-point')
