@pragma('vm:entry-point')
double totalScheduledPassTime(List<String> ops) {
  final stack = <double>[];
  for (final op in ops) {
    if (op == 'CANCEL') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(double.parse(op.split(' ')[1]));
    }
  }
  double total = 0.0;
  for (final d in stack) {
    total += d;
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(totalScheduledPassTime(['PASS 3.5', 'PASS 2.0', 'CANCEL']) == 3.5);
  assert(totalScheduledPassTime([]) == 0.0);
  assert(totalScheduledPassTime(['PASS 1.0', 'PASS 2.0', 'PASS 3.0']) == 6.0);
