@pragma('vm:entry-point')
String normalizeSeatChart(String spec) {
  final seats = <String, Set<int>>{};
  for (final raw in spec.split(',')) {
    final token = raw.trim();
    if (token.isEmpty) continue;
    final m = RegExp(r'^([A-Z])(\d+)(?:-([A-Z])?(\d+))?$').firstMatch(token);
    if (m == null) return 'ERR:$token';
    final row = m.group(1)!;
    final start = int.parse(m.group(2)!);
    var end = start;
    if (m.group(4) != null) {
      if (m.group(3) != null && m.group(3) != row) return 'ERR:$token';
      end = int.parse(m.group(4)!);
    }
    if (start < 1 || end < start) return 'ERR:$token';
    final set = seats.putIfAbsent(row, () => <int>{});
    for (var s = start; s <= end; s++) {
      set.add(s);
    }
  }
  if (seats.isEmpty) return '';
  final rows = seats.keys.toList()..sort();
  final parts = <String>[];
  for (final row in rows) {
    final nums = seats[row]!.toList()..sort();
    final runs = <String>[];
    var i = 0;
    while (i < nums.length) {
      var j = i;
      while (j + 1 < nums.length && nums[j + 1] == nums[j] + 1) {
        j++;
      }
      runs.add(i == j ? '$row${nums[i]}' : '$row${nums[i]}-${nums[j]}');
      i = j + 1;
    }
    parts.add(runs.join(','));
  }
  return parts.join(';');
}

@pragma('vm:entry-point')
void main() {
  assert(normalizeSeatChart('A1,A2,A3') == 'A1-3');
  assert(normalizeSeatChart('B5, A2-4, A3') == 'A2-4;B5');
  assert(normalizeSeatChart('A3-B5') == 'ERR:A3-B5');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = normalizeSeatChart;

  expect(candidate('A1,A2,A3'), 'A1-3');
  expect(candidate('B5, A2-4, A3'), 'A2-4;B5');
  expect(candidate(''), '');
  expect(candidate('A1-A3,C7'), 'A1-3;C7');
  expect(candidate('A3-B5'), 'ERR:A3-B5');
  expect(candidate('A0'), 'ERR:A0');
  expect(candidate('A5-3'), 'ERR:A5-3');
  expect(candidate('D10-12, D11, D14'), 'D10-12,D14');
