int minutesUntilNextTrain(int currentMinute, List<int> departures) {
  // currentMinute and each departure are minutes since midnight (0..1439).
  // Returns the wait in minutes until the next departure, wrapping past
  // midnight to the next day if needed. Returns -1 if there are no trains.
  if (departures.isEmpty) return -1;
  int best = 1440;
  for (final d in departures) {
    final wait = (d - currentMinute) % 1440;
    if (wait < best) best = wait;
  }
  return best;
}

