double tideRiseFromSensorFlags(int flags) {
  // Each set bit i in `flags` marks a recorded tide pulse at slot i.
  // Pulses at even slots raise the tide by 0.5 m, odd slots by 0.25 m.
  double total = 0.0;
  int slot = 0;
  int f = flags;
  while (f > 0) {
    if ((f & 1) == 1) {
      total += (slot % 2 == 0) ? 0.5 : 0.25;
    }
    f >>= 1;
    slot++;
  }
  return total;
}

