  assert(thermostatScheduleCoverage([[0, 18, 60, 22]]) == 'area=240,overlap=0');
  assert(thermostatScheduleCoverage([[0, 18, 60, 22], [30, 20, 90, 24]]) == 'area=420,overlap=60');
  assert(thermostatScheduleCoverage([]) == 'area=0,overlap=0');
  print('All tests passed!');
}

