@pragma('vm:entry-point')
String quadraticProbeBucketReport(int keys, int loadNum, int loadDen) {
  // A hash table using quadratic probing keeps every probe sequence
  // complete when the bucket count is a prime p with p % 4 == 3.
  // Given an expected key count and a maximum load factor expressed as
  // the fraction loadNum/loadDen, the minimum bucket count is
  // ceil(keys * loadDen / loadNum). Find the smallest prime p >= that
  // minimum (and >= 3) with p % 4 == 3, counting how many primes had to
  // be skipped along the way because they were congruent to 1 mod 4.
  // Returns 'p|skipped'.
  int pMin;
  if (keys <= 0) {
    pMin = 3;
  } else {
    pMin = (keys * loadDen + loadNum - 1) ~/ loadNum;
  }
  if (pMin < 3) pMin = 3;
  bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (int d = 3; d * d <= n; d += 2) {
      if (n % d == 0) return false;
    }
    return true;
  }
  int skipped = 0;
  int p = pMin;
  while (true) {
    if (isPrime(p)) {
      if (p % 4 == 3) return '$p|$skipped';
      skipped++;
    }
    p++;
  }
}

