double firstBucketAtCapacity(List<int> counts, int threshold) {
  // counts is sorted ascending; find index of the first hash bucket
  // whose item count is >= threshold. Return -1.0 if no such bucket.
  int lo = 0;
  int hi = counts.length;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (counts[mid] >= threshold) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return lo < counts.length ? lo.toDouble() : -1.0;
}

