@pragma('vm:entry-point')
double parseManifestTotalWeight(String manifest) {
  // Manifest format: entries separated by ';'.
  // Each entry: "label:qty@unitWeight", e.g. "boxA:2@2.5".
  // A label prefixed with '!' marks fragile cargo: its weight counts 1.5x
  // (extra packaging). Malformed entries are skipped entirely.
  double total = 0.0;
  for (final entry in manifest.split(';')) {
    final trimmed = entry.trim();
    if (trimmed.isEmpty) continue;
    final colon = trimmed.indexOf(':');
    if (colon <= 0) continue;
    var label = trimmed.substring(0, colon);
    final spec = trimmed.substring(colon + 1);
    bool fragile = false;
    if (label.startsWith('!')) {
      fragile = true;
      label = label.substring(1);
    }
    if (label.isEmpty) continue;
    final at = spec.indexOf('@');
    if (at <= 0 || at == spec.length - 1) continue;
    final qty = int.tryParse(spec.substring(0, at));
    final weight = double.tryParse(spec.substring(at + 1));
    if (qty == null || weight == null || qty < 0 || weight < 0) continue;
    double subtotal = qty * weight;
    if (fragile) subtotal *= 1.5;
    total += subtotal;
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(parseManifestTotalWeight('boxA:2@2.5;boxB:1@4.0') == 9.0);
  assert(parseManifestTotalWeight('!glass:2@2.0') == 6.0);
  assert(parseManifestTotalWeight('') == 0.0);
  print('All tests passed!');
}

