@pragma('vm:entry-point')
List<int> smallestWindowCoveringAllSeverities(List<int> severities) {
  // Each entry in `severities` is the severity code of one server log line.
  // Find the shortest contiguous block of log lines that contains at least
  // one line of EVERY distinct severity present in the whole log.
  // Returns [startIndex, length]; ties broken by leftmost start.
  // Returns [-1, 0] for an empty log.
  if (severities.isEmpty) return [-1, 0];
  final needed = severities.toSet().length;
  final counts = <int, int>{};
  int left = 0;
  int have = 0;
  int bestStart = 0;
  int bestLen = severities.length + 1;
  for (int right = 0; right < severities.length; right++) {
    final s = severities[right];
    counts[s] = (counts[s] ?? 0) + 1;
    if (counts[s] == 1) have++;
    while (have == needed) {
      final len = right - left + 1;
      if (len < bestLen) {
        bestLen = len;
        bestStart = left;
      }
      final l = severities[left];
      counts[l] = counts[l]! - 1;
      if (counts[l] == 0) have--;
      left++;
    }
  }
  return [bestStart, bestLen];
}

