@pragma('vm:entry-point')
List<String> splitBillCents(int totalCents, List<int> weights) {
  if (weights.isEmpty) return <String>[];
  final int n = weights.length;
  final int sumW = weights.fold(0, (a, b) => a + b);
  final List<int> lo = List<int>.filled(n, 0);
  final List<int> hi = List<int>.filled(n, 0);
  for (int i = 0; i < n; i++) {
    final int prod = totalCents * weights[i];
    lo[i] = prod ~/ sumW;
    hi[i] = prod % sumW == 0 ? lo[i] : lo[i] + 1;
  }
  final List<int> sufLo = List<int>.filled(n + 1, 0);
  final List<int> sufHi = List<int>.filled(n + 1, 0);
  for (int i = n - 1; i >= 0; i--) {
    sufLo[i] = sufLo[i + 1] + lo[i];
    sufHi[i] = sufHi[i + 1] + hi[i];
  }
  final List<int> chosen = List<int>.filled(n, 0);
  bool solve(int i, int remaining) {
    if (i == n) return remaining == 0;
    final List<int> options =
        lo[i] == hi[i] ? <int>[lo[i]] : <int>[lo[i], hi[i]];
    for (final int c in options) {
      final int rest = remaining - c;
      if (rest >= sufLo[i + 1] && rest <= sufHi[i + 1]) {
        chosen[i] = c;
        if (solve(i + 1, rest)) return true;
      }
    }
    return false;
  }
  solve(0, totalCents);
  return chosen
      .map((c) => '\$${c ~/ 100}.${(c % 100).toString().padLeft(2, '0')}')
      .toList();
}

