@pragma('vm:entry-point')
int thermostatTempAt(List<List<int>> schedule, int minute) {
  // Each entry is [startMinute, priority, temp]. Entries repeat daily.
  // The active entry at a given minute is the one with the greatest
  // startMinute <= minute; if none exists, the day wraps around and the
  // entry with the greatest startMinute overall (yesterday's last) applies.
  // Ties on startMinute: higher priority wins; if priority also ties,
  // the lower (energy-saving) temperature wins. Returns -1 for empty input.
  if (schedule.isEmpty) return -1;
  final int m = ((minute % 1440) + 1440) % 1440;
  final entries = schedule.map((e) => List<int>.from(e)).toList();
  entries.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    if (a[1] != b[1]) return b[1].compareTo(a[1]);
    return a[2].compareTo(b[2]);
  });
  int targetStart = -1;
  for (final e in entries) {
    if (e[0] <= m && e[0] > targetStart) {
      targetStart = e[0];
    }
  }
  if (targetStart == -1) {
    // Wrap around midnight: latest start of the previous day applies.
    targetStart = entries.last[0];
  }
  for (final e in entries) {
    if (e[0] == targetStart) return e[2];
  }
  return -1;
}

@pragma('vm:entry-point')
void main() {
  assert(thermostatTempAt([[360, 1, 68], [480, 2, 72], [1320, 1, 62]], 400) == 68);
  assert(thermostatTempAt([[360, 1, 68], [480, 2, 72], [1320, 1, 62]], 100) == 62);
  assert(thermostatTempAt([], 500) == -1);
  print('All tests passed!');
}

