double elevatorRequestMidpoint(List<int> requests, int currentFloor) {
  if (requests.isEmpty) {
    return 0.0;
  }

  List<int> ordered = List<int>.from(requests);
  ordered.sort((a, b) {
    int distanceA = (a - currentFloor).abs();
    int distanceB = (b - currentFloor).abs();
    if (distanceA != distanceB) {
      return distanceA.compareTo(distanceB);
    }
    return a.compareTo(b);
  });

  return (ordered.first + ordered.last) / 2;
}

