@pragma('vm:entry-point')
List<String> satelliteRelayPlans(List<String> windows, int maxGap) {
  List<Map<String, Object>> parsed = [];
  for (String window in windows) {
    List<String> parts = window.split(':');
    List<String> times = parts[1].split('-');
    parsed.add({
      'name': parts[0],
      'start': int.parse(times[0]),
      'end': int.parse(times[1]),
    });
  }

  parsed.sort((a, b) => (a['start'] as int).compareTo(b['start'] as int));

  List<String> result = [];

  void search(int index, List<String> path, int lastEnd) {
    if (path.length >= 2) {
      result.add(path.join('>'));
    }

    for (int i = index; i < parsed.length; i++) {
      int start = parsed[i]['start'] as int;
      int end = parsed[i]['end'] as int;
      String name = parsed[i]['name'] as String;

      if (start >= lastEnd && start - lastEnd <= maxGap) {
        path.add(name);
        search(i + 1, path, end);
        path.removeLast();
      }
    }
  }

  for (int i = 0; i < parsed.length; i++) {
    search(
      i + 1,
      [parsed[i]['name'] as String],
      parsed[i]['end'] as int,
    );
  }

  return result;
}

