  assert(spellEditConfidence('teh cat', 'the cat', 'REP:teh->the') == 1.0);
  assert(spellEditConfidence('blue blu car', 'blue car', 'DEL:blu') == 0.5);
  assert(spellEditConfidence('abc', 'abc', 'REP:xyz->abc') == -0.5);
  print('All tests passed!');
}

