void main() {
  assert(canProcessElevatorRequests(28, 0, 2, 8) == true);
  assert(canProcessElevatorRequests(84, 0, 2, 8) == false);
  assert(canProcessElevatorRequests(24, 8, 3, 8) == false);
  print('All tests passed!');
}

