String compactInventory(List<String> items) {
  Map<String, int> counts = {};
  List<String> order = [];

  for (String item in items) {
    if (!counts.containsKey(item)) {
      order.add(item);
    }
    counts[item] = (counts[item] ?? 0) + 1;
  }

  List<String> parts = [];
  for (String item in order) {
    parts.add('$item x${counts[item]}');
