@pragma('vm:entry-point')
Set<int> flaggedManifestContainers(List<String> manifests) {
  bool isPrime(int value) {
    if (value < 2) {
      return false;
    }
    for (int i = 2; i * i <= value; i++) {
      if (value % i == 0) {
        return false;
      }
    }
    return true;
  }

  final Map<int, Map<String, int>> shipCounts = {};
  final Map<int, Map<String, Set<String>>> shipPorts = {};
  final Map<int, int> totals = {};

  for (final entry in manifests) {
    final parts = entry.split('|');
    if (parts.length != 3) {
      continue;
    }

    final String ship = parts[0];
    final int? containerId = int.tryParse(parts[1]);
    final String port = parts[2];

    if (ship.isEmpty || containerId == null || port.isEmpty) {
      continue;
    }

    shipCounts.putIfAbsent(containerId, () => {});
    shipPorts.putIfAbsent(containerId, () => {});

    shipCounts[containerId]![ship] =
        (shipCounts[containerId]![ship] ?? 0) + 1;

    shipPorts[containerId]!
        .putIfAbsent(ship, () => <String>{})
        .add(port);

    totals[containerId] = (totals[containerId] ?? 0) + 1;
  }

  final Set<int> flagged = {};

  for (final containerId in shipCounts.keys) {
    final counts = shipCounts[containerId]!;
    if (counts.length < 2 || !isPrime(totals[containerId]!)) {
      continue;
    }

    int minCount = totals[containerId]!;
    int maxCount = 0;
    final Set<String> seenPorts = {};
    bool disjointPorts = true;

    for (final ship in counts.keys) {
      final count = counts[ship]!;
      if (count < minCount) {
        minCount = count;
      }
      if (count > maxCount) {
        maxCount = count;
      }

      for (final port in shipPorts[containerId]![ship]!) {
        if (!seenPorts.add(port)) {
          disjointPorts = false;
        }
      }
    }

    if (maxCount - minCount <= 1 && disjointPorts) {
      flagged.add(containerId);
    }
  }

  return flagged;
}

