@pragma('vm:entry-point')
Map<String, int> analyzeAsciiRowTimeline(List<String> rows, int daysPerRow) {
  int firstArtDay = -1;
  int lastArtDay = -1;
  int longestBreak = 0;
  int currentBreak = 0;
  int longestStreak = 0;
  int currentStreak = 0;
  bool seenArt = false;

  for (int row = 0; row < rows.length; row++) {
    String line = rows[row];

    for (int col = 0; col < daysPerRow && col < line.length; col++) {
      int dayIndex = row * daysPerRow + col;
      String cell = line[col];

      if (cell == '#') {
        if (firstArtDay == -1) {
          firstArtDay = dayIndex;
        }

        lastArtDay = dayIndex;
        seenArt = true;

        if (currentBreak > longestBreak) {
          longestBreak = currentBreak;
        }

        currentBreak = 0;
        currentStreak++;

        if (currentStreak > longestStreak) {
          longestStreak = currentStreak;
        }
      } else {
        currentStreak = 0;

        if (seenArt) {
          currentBreak++;
        }
      }
    }
  }

  return {
    'firstArtDay': firstArtDay,
    'lastArtDay': lastArtDay,
    'longestBreak': longestBreak,
    'longestStreak': longestStreak,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeAsciiRowTimeline(['#..', '#.#'], 3)['longestBreak'] == 2);
  assert(analyzeAsciiRowTimeline(['###', '##.'], 3)['longestStreak'] == 5);
  assert(analyzeAsciiRowTimeline([], 4).toString() == '{firstArtDay: -1, lastArtDay: -1, longestBreak: 0, longestStreak: 0}');
  print('All tests passed!');
}

