  expect(candidate(['#.#', '.##'], 3).toString(), '{firstArtDay: 0, lastArtDay: 5, longestBreak: 1, longestStreak: 2}');
  expect(candidate(['##', '..', '##'], 2).toString(), '{firstArtDay: 0, lastArtDay: 5, longestBreak: 2, longestStreak: 2}');
  expect(candidate(['...'], 3).toString(), '{firstArtDay: -1, lastArtDay: -1, longestBreak: 0, longestStreak: 0}');
