List<String> inventoryAfterUndos(List<String> actions) {
  List<String> inventory = [];
  List<String> removed = [];

  for (String action in actions) {
    if (action.startsWith('ADD:')) {
      inventory.add(action.substring(4));
    } else if (action == 'REMOVE' && inventory.isNotEmpty) {
      removed.add(inventory.removeLast());
    } else if (action == 'UNDO' && removed.isNotEmpty) {
      inventory.add(removed.removeLast());
