  assert(findClosestRgbPixels(['0,0,0', '10,10,10'], [5]).toString() == '[0,0,0]');
  assert(findClosestRgbPixels(['1,1,1', '2,2,2', '3,3,3'], [6]).toString() == '[2,2,2]');
  assert(findClosestRgbPixels([], [3, 7]).toString() == '[none, none]');
