  assert(encodeBatteryCycleLayers([]) == '');
  assert(encodeBatteryCycleLayers([[50]]) == 'S1');
  assert(encodeBatteryCycleLayers([[90, 90], [10, 10]]) == 'O2D2');
  print('All tests passed!');
}

