String orderedServerLogs(List<String> logs) {
  List<String> sorted = List<String>.from(logs);
  Map<String, int> priority = {
    'ERROR': 0,
    'WARN': 1,
    'INFO': 2,
  };
  sorted.sort((a, b) {
    String levelA = a.split(' ')[0];
    String levelB = b.split(' ')[0];
    int diff = priority[levelA]!.compareTo(priority[levelB]!);
    return diff != 0 ? diff : a.compareTo(b);
  });
  return sorted.join('|');
}

@pragma('vm:entry-point')
void main() {
  assert(orderedServerLogs(['INFO boot', 'ERROR disk']) == 'ERROR disk|INFO boot');
  assert(orderedServerLogs(['WARN cpu', 'WARN memory']) == 'WARN cpu|WARN memory');
  assert(orderedServerLogs([]) == '');
  print('All tests passed!');
}

tests:
