  final candidate = orderedServerLogs;

  expect(candidate(['INFO start', 'ERROR crash', 'WARN retry']), 'ERROR crash|WARN retry|INFO start');
  expect(candidate(['WARN cpu', 'WARN memory', 'WARN cache']), 'WARN cache|WARN cpu|WARN memory');
  expect(candidate(['INFO beta', 'INFO alpha']), 'INFO alpha|INFO beta');
  expect(candidate(['ERROR zeta']), 'ERROR zeta');
  expect(candidate([]), '');
  expect(candidate(['INFO sync', 'ERROR boot', 'ERROR api']), 'ERROR api|ERROR boot|INFO sync');
  expect(candidate(['WARN timeout', 'INFO ready', 'WARN crash']), 'WARN crash|WARN timeout|INFO ready');
  expect(candidate(['INFO a', 'WARN a', 'ERROR a']), 'ERROR a|WARN a|INFO a');
}

