@pragma('vm:entry-point')
List<String> buildElevatorServicePlan(int currentFloor, List<int> requests) {
  Set<int> seen = <int>{};
  List<int> up = <int>[];
  List<int> down = <int>[];
  bool openCurrent = false;

  for (int floor in requests) {
    if (floor < -2 || floor > 20) {
      continue;
    }
    if (seen.contains(floor)) {
      continue;
    }
    seen.add(floor);

    if (floor == currentFloor) {
      openCurrent = true;
    } else if (floor > currentFloor) {
      up.add(floor);
    } else {
      down.add(floor);
    }
  }

  up.sort();
  down.sort((a, b) => b.compareTo(a));

  List<String> plan = <String>[];

  if (openCurrent) {
    plan.add('OPEN:$currentFloor');
  }

  List<List<int>> groups = <List<int>>[up, down];
  List<String> labels = <String>['UP', 'DOWN'];

  for (int i = 0; i < groups.length; i++) {
    List<int> group = groups[i];

    for (int j = 0; j < group.length; j++) {
      int start = group[j];
      int end = start;

      while (j + 1 < group.length) {
        int next = group[j + 1];
        bool consecutive = labels[i] == 'UP'
            ? next == end + 1
            : next == end - 1;

        if (!consecutive) {
          break;
        }

        end = next;
        j++;
      }

      if (start == end) {
        plan.add('${labels[i]}:$start');
      } else {
        plan.add('${labels[i]}:$start->$end');
      }
    }
  }

  return plan;
}

@pragma('vm:entry-point')
void main() {
  assert(buildElevatorServicePlan(5, <int>[5, 6, 7, 9]).toString() == '[OPEN:5, UP:6->7, UP:9]');
  assert(buildElevatorServicePlan(0, <int>[-1, -2, -2, 1]).length == 2);
  assert(buildElevatorServicePlan(3, <int>[30, 31]).toString() == '[]');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = buildElevatorServicePlan;

  expect(candidate(5, <int>[5, 6, 7, 9]), <String>['OPEN:5', 'UP:6->7', 'UP:9']);
  expect(candidate(0, <int>[-2, -1, 1, 2, 4]), <String>['UP:1->2', 'UP:4', 'DOWN:-1->-2']);
  expect(candidate(3, <int>[3, 3, 2, 2, 4, 5, 5]), <String>['OPEN:3', 'UP:4->5', 'DOWN:2']);
  expect(candidate(10, <int>[12, 11, 10, 9, 8]), <String>['OPEN:10', 'UP:11->12', 'DOWN:9->8']);
  expect(candidate(1, <int>[]), <String>[]);
  expect(candidate(1, <int>[30, -5, 1]), <String>['OPEN:1']);
  expect(candidate(-1, <int>[-2, 0, 1, 3]), <String>['UP:0->1', 'UP:3', 'DOWN:-2']);
}

