Set<int> manhattanReachableSquares(int row, int col, int distance) {
  Set<int> squares = {};
  for (int r = 0; r < 8; r++) {
    for (int c = 0; c < 8; c++) {
      int steps = (r - row).abs() + (c - col).abs();
      if (steps <= distance) {
        squares.add(r * 8 + c);
      }
    }
  }
  return squares;
}

@pragma('vm:entry-point')
void main() {
  assert(manhattanReachableSquares(0, 0, 0).length == 1);
  assert(manhattanReachableSquares(3, 3, 1).length == 5);
  assert(manhattanReachableSquares(7, 7, 2).contains(61));
  print('All tests passed!');
}

