@pragma('vm:entry-point')
Set<int> risingTideRecoveryDays(List<int> heights, int safeLevel, int maxRecoveryDays) {
  Set<int> recoveryDays = <int>{};

  for (int i = 0; i < heights.length; i++) {
    bool startsDip = heights[i] < safeLevel &&
        (i == 0 || heights[i - 1] >= safeLevel);

    if (startsDip) {
      int previous = heights[i];
      int foundDay = -1;

      for (int step = 1;
          step <= maxRecoveryDays && i + step < heights.length;
          step++) {
        int current = heights[i + step];

        if (current <= previous) {
          break;
        }

        if (current >= safeLevel) {
          foundDay = i + step;
          break;
        }

        previous = current;
      }

      if (foundDay != -1) {
        recoveryDays.add(foundDay);
      }
    }
  }

  return recoveryDays;
}

@pragma('vm:entry-point')
void main() {
  assert(risingTideRecoveryDays([2, 3, 5], 4, 2).contains(2));
  assert(risingTideRecoveryDays([5, 2, 1, 4, 5], 4, 4).length == 0);
  assert(risingTideRecoveryDays([5, 2, 3, 4, 1, 2, 5], 4, 3).length == 2);
  print('All tests passed!');
}

