@pragma('vm:entry-point')
bool validateQrModuleLayout(String layout, int size) {
  if (size <= 0 || layout.isEmpty) {
    return false;
  }

  List<String> rows = layout.split('/');
  if (rows.length != size) {
    return false;
  }

  for (String row in rows) {
    if (row.isEmpty) {
      return false;
    }

    List<String> tokens = row.split(',');
    int moduleCount = 0;
    String lastColor = '';

    for (String token in tokens) {
      if (token.length < 2) {
        return false;
      }

      String color = token[0];
      if (color != 'B' && color != 'W') {
        return false;
      }

      String countText = token.substring(1);
      if (countText.startsWith('0')) {
        return false;
      }

      int? count = int.tryParse(countText);
      if (count == null || count <= 0) {
        return false;
      }

      if (color == lastColor) {
        return false;
      }

      moduleCount += count;
      lastColor = color;
    }

    if (moduleCount != size) {
      return false;
    }
  }

  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(validateQrModuleLayout('B2,W1/W1,B2/B1,W2', 3) == true);
  assert(validateQrModuleLayout('B1,B2/W3/W1,B2', 3) == false);
  assert(validateQrModuleLayout('B2,W2/W1,B3', 4) == false);
  print('All tests passed!');
}

