Set<int> remainingPacketSizes(List<String> events) {
  List<int> stack = [];

  for (String event in events) {
    if (event.startsWith('ADD ')) {
      int size = int.parse(event.substring(4));
      stack.add(size);
    } else if (event == 'UNDO' && stack.isNotEmpty) {
      stack.removeLast();
    }
  }

  return stack.toSet();
}

@pragma('vm:entry-point')
void main() {
  assert(remainingPacketSizes(['ADD 64', 'ADD 128']).toString() == '{64, 128}');
  assert(remainingPacketSizes(['ADD 64', 'UNDO']).isEmpty);
  assert(remainingPacketSizes(['UNDO', 'ADD 512']).toString() == '{512}');
  print('All tests passed!');
}

