@pragma('vm:entry-point')
Map<String, int> decodeElevatorRequestMetrics(String stream, int shift) {
  int currentFloor = 0;
  int served = 0;
  int checksum = 0;
  int invalid = 0;

  if (stream.isEmpty) {
    return {
      'finalFloor': 0,
      'served': 0,
      'checksum': 0,
      'invalid': 0,
    };
  }

  String decode(String text) {
    StringBuffer out = StringBuffer();
    for (int i = 0; i < text.length; i++) {
      int code = text.codeUnitAt(i);
      if (code >= 65 && code <= 90) {
        int shifted = ((code - 65 - shift) % 26 + 26) % 26;
        out.writeCharCode(65 + shifted);
      } else {
        out.writeCharCode(code);
      }
    }
    return out.toString();
  }

  List<String> parts = decode(stream).split('|');

  for (String token in parts) {
    if (token.isEmpty) {
      invalid++;
      continue;
    }

    int index = 0;
    while (index < token.length) {
      int code = token.codeUnitAt(index);
      if (code < 48 || code > 57) {
        break;
      }
      index++;
    }

    int repeat = index == 0 ? 1 : int.parse(token.substring(0, index));

    if (repeat <= 0 || index >= token.length) {
      invalid++;
      continue;
    }

    String direction = token[index];
    if (direction != 'U' && direction != 'D') {
      invalid++;
      continue;
    }

    String amountText = token.substring(index + 1);
    if (amountText.isEmpty) {
      invalid++;
      continue;
    }

    bool numeric = true;
    for (int i = 0; i < amountText.length; i++) {
      int code = amountText.codeUnitAt(i);
      if (code < 48 || code > 57) {
        numeric = false;
        break;
      }
    }

    if (!numeric) {
      invalid++;
      continue;
    }

    int amount = int.parse(amountText);

    for (int i = 0; i < repeat; i++) {
      currentFloor += direction == 'U' ? amount : -amount;
      served++;
      checksum = (checksum * 31 + currentFloor + served) % 100000;
      if (checksum < 0) {
        checksum += 100000;
      }
    }
  }

  return {
    'finalFloor': currentFloor,
    'served': served,
    'checksum': checksum,
    'invalid': invalid,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(decodeElevatorRequestMetrics('', 4)['served'] == 0);
  assert(decodeElevatorRequestMetrics('2V3|E2', 1).toString() == '{finalFloor: 4, served: 3, checksum: 4099, invalid: 0}');
  assert(decodeElevatorRequestMetrics('0U2|D1', 0)['invalid'] == 1);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = decodeElevatorRequestMetrics;

  expect(candidate('', 3).toString(), '{finalFloor: 0, served: 0, checksum: 0, invalid: 0}');
  expect(candidate('2V3|E2', 1).toString(), '{finalFloor: 4, served: 3, checksum: 4099, invalid: 0}');
  expect(candidate('UX|3D1', 0).toString(), '{finalFloor: -3, served: 3, checksum: 0, invalid: 1}');
  expect(candidate('U2|2D1', 0).toString(), '{finalFloor: 0, served: 3, checksum: 2979, invalid: 0}');
  expect(candidate('3W2', 2).toString(), '{finalFloor: 6, served: 3, checksum: 3078, invalid: 0}');
  expect(candidate('0U2|D1', 0).toString(), '{finalFloor: -1, served: 1, checksum: 0, invalid: 1}');
  expect(candidate('U1||D1', 0).toString(), '{finalFloor: 0, served: 2, checksum: 64, invalid: 1}');
