@pragma('vm:entry-point')
List<int> summarizeStableElectionLeads(List<int> leaders, int stabilityWindow) {
  if (leaders.isEmpty) {
    return <int>[];
  }

  final List<List<int>> segments = <List<int>>[];
  int current = leaders[0];
  int length = 1;

  for (int i = 1; i < leaders.length; i++) {
    if (leaders[i] == current) {
      length++;
    } else {
      segments.add(<int>[current, length]);
      current = leaders[i];
      length = 1;
    }
  }
  segments.add(<int>[current, length]);

  final Map<int, int> appearances = <int, int>{};
  for (final List<int> segment in segments) {
    appearances[segment[0]] = (appearances[segment[0]] ?? 0) + 1;
  }

  final List<List<int>> filtered = <List<int>>[];

  for (int i = 0; i < segments.length; i++) {
    final int candidate = segments[i][0];
    final int span = segments[i][1];
    final bool edgeSegment = i == 0 || i == segments.length - 1;

    final bool keep = span >= stabilityWindow ||
        (appearances[candidate] ?? 0) > 1 ||
        edgeSegment;

    if (!keep) {
      continue;
    }

    if (filtered.isNotEmpty && filtered.last[0] == candidate) {
      filtered.last[1] += span;
    } else {
      filtered.add(<int>[candidate, span]);
    }
  }

  final List<int> result = <int>[];
  for (final List<int> segment in filtered) {
    result.add(segment[0]);
    result.add(segment[1]);
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(summarizeStableElectionLeads(<int>[1, 1, 2, 3, 1, 1], 2).toString() == '[1, 4]');
  assert(summarizeStableElectionLeads(<int>[], 3).length == 0);
  assert(summarizeStableElectionLeads(<int>[4, 4, 4], 2).toString() == '[4, 3]');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = summarizeStableElectionLeads;

  expect(candidate(<int>[], 2).toString(), '[]');
  expect(candidate(<int>[7], 3).toString(), '[7, 1]');
  expect(candidate(<int>[1, 1, 2, 3, 1, 1], 2).toString(), '[1, 4]');
  expect(candidate(<int>[1, 1, 2, 3, 3, 2, 2, 1], 2).toString(), '[1, 2, 2, 1, 3, 2, 2, 2, 1, 1]');
