void main() {
  assert(scanWifiSignalBins('').length == 0);
  assert(scanWifiSignalBins('ap[S20,?,+25,?]').toString() == '[ap:weak, ap:fair]');
  assert(scanWifiSignalBins('x[S50,?,!,?,?]').toString() == '[x:fair, x:lost, x:dead]');
  print('All tests passed!');
}

