@pragma('vm:entry-point')
Set<int> streakBonusRounds(List<List<int>> rounds) {
  Set<int> result = {};

  for (int i = 0; i < rounds.length; i++) {
    Map<int, int> counts = {};

    for (int value in rounds[i]) {
      counts[value] = (counts[value] ?? 0) + 1;
    }

    Map<int, Set<int>> groupedByFrequency = {};
    int highestFrequency = 0;

    counts.forEach((face, frequency) {
      groupedByFrequency.putIfAbsent(frequency, () => <int>{}).add(face);

      if (frequency > highestFrequency) {
        highestFrequency = frequency;
      }
    });

    bool uniqueLeader =
        groupedByFrequency.containsKey(highestFrequency) &&
        groupedByFrequency[highestFrequency]!.length == 1;

    bool sharedLowerFrequency = false;

    groupedByFrequency.forEach((frequency, faces) {
      if (frequency != highestFrequency && faces.length >= 3) {
        sharedLowerFrequency = true;
      }
    });

    if (uniqueLeader && sharedLowerFrequency) {
      result.add(i);
    }
  }

  return result;
}

