@pragma('vm:entry-point')
String planElevatorSweepOrder(int currentFloor, List<int> requests) {
  if (requests.isEmpty) {
    return 'idle';
  }

  Map<int, int> counts = {};
  for (int floor in requests) {
    counts[floor] = (counts[floor] ?? 0) + 1;
  }

  int above = 0;
  int below = 0;
  int nearestDistance = 1 << 30;
  bool sweepUp = true;

  for (int floor in counts.keys) {
    if (floor > currentFloor) {
      above += counts[floor]!;
    } else if (floor < currentFloor) {
      below += counts[floor]!;
    }

    int distance = (floor - currentFloor).abs();
    if (distance < nearestDistance) {
      nearestDistance = distance;
      sweepUp = floor >= currentFloor;
    } else if (distance == nearestDistance && floor >= currentFloor) {
      sweepUp = true;
    }
  }

  if (above > below) {
    sweepUp = true;
  } else if (below > above) {
    sweepUp = false;
  }

  List<int> ordered = counts.keys.toList();
  ordered.sort((a, b) {
    if (a == currentFloor && b != currentFloor) {
      return -1;
    }
    if (b == currentFloor && a != currentFloor) {
      return 1;
    }

    bool aPrimary = sweepUp ? a >= currentFloor : a <= currentFloor;
    bool bPrimary = sweepUp ? b >= currentFloor : b <= currentFloor;

    if (aPrimary != bPrimary) {
      return aPrimary ? -1 : 1;
    }

    int countCompare = counts[b]!.compareTo(counts[a]!);
    if (countCompare != 0) {
      return countCompare;
    }

    if (aPrimary) {
      return sweepUp ? a.compareTo(b) : b.compareTo(a);
    }

    return sweepUp ? b.compareTo(a) : a.compareTo(b);
  });

  List<String> parts = [];
  for (int floor in ordered) {
    int count = counts[floor]!;
    parts.add(count > 1 ? '${floor}x$count' : '$floor');
  }

  return parts.join(' -> ');
}

@pragma('vm:entry-point')
void main() {
  assert(planElevatorSweepOrder(5, []) == 'idle');
  assert(planElevatorSweepOrder(5, [7, 7, 3]) == '7x2 -> 3');
  assert(planElevatorSweepOrder(10, [10, 8, 12, 8]) == '10 -> 8x2 -> 12');
  print('All tests passed!');
}

