  assert(countUsableSeatBlocks(4, 2, [0, 2], [0, 1], [2, 2]) == 2);
  assert(countUsableSeatBlocks(5, 3, [1], [0], [1]) == 1);
  assert(countUsableSeatBlocks(3, 4, [0], [0], [2]) == 0);
  print('All tests passed!');
}

