void main() {
  assert(suggestNearbySpellings('cta', ['cat', 'cut', 'cast'], 1).length == 1);
  assert(suggestNearbySpellings('', ['a', 'bb', ''], 0).toString() == '[]');
  assert(suggestNearbySpellings('speling', ['spelling', 'spieling', 'selling'], 2).toString() == '[spelling]');
  print('All tests passed!');
}

