List<int> dnaMaskWindows(String dna, int rotateBits) {
  List<int> result = [];

  for (int start = 0; start < dna.length; start += 4) {
    int encoded = 0;
    int flags = 0;
    int bitLength = 0;

    for (int i = start; i < start + 4 && i < dna.length; i++) {
      int code = 0;
      String ch = dna[i];

      if (ch == 'C') {
        code = 1;
      } else if (ch == 'G') {
        code = 2;
      } else if (ch == 'T') {
        code = 3;
      }

      encoded = (encoded << 2) | code;
      flags |= 1 << code;
      bitLength += 2;
    }

    int mask = (1 << bitLength) - 1;
    int shift = bitLength == 0 ? 0 : rotateBits % bitLength;
    int rotated = encoded;

    if (shift > 0) {
      rotated = ((encoded << shift) & mask) | (encoded >> (bitLength - shift));
    }

    int mixed = rotated ^ flags;
    int count = 0;

    while (mixed > 0) {
      count += mixed & 1;
      mixed >>= 1;
    }

    result.add(count);
  }

  return result;
}

