@pragma('vm:entry-point')
double highestStableManifestYield(List<int> crateWeights, int maxSpread, int handlingPenalty) {
  if (crateWeights.isEmpty || maxSpread < 0) {
    return 0.0;
  }

  List<int> maxDeque = <int>[];
  List<int> minDeque = <int>[];

  int left = 0;
  int sum = 0;
  int bestUnits = -1 << 30;

  for (int right = 0; right < crateWeights.length; right++) {
    int value = crateWeights[right];
    sum += value;

    while (maxDeque.isNotEmpty && crateWeights[maxDeque.last] <= value) {
      maxDeque.removeLast();
    }
    maxDeque.add(right);

    while (minDeque.isNotEmpty && crateWeights[minDeque.last] >= value) {
      minDeque.removeLast();
    }
    minDeque.add(right);

    while (crateWeights[maxDeque.first] - crateWeights[minDeque.first] > maxSpread) {
      sum -= crateWeights[left];

      if (maxDeque.first == left) {
        maxDeque.removeAt(0);
      }
      if (minDeque.first == left) {
        minDeque.removeAt(0);
      }

      left++;
    }

    int windowLength = right - left + 1;
    int yieldUnits = sum - handlingPenalty * (windowLength - 1);

    if (yieldUnits > bestUnits) {
      bestUnits = yieldUnits;
    }
  }

  return bestUnits / 4.0;
}

