  assert(orderRgbPixelsByContrast([]).length == 0);
  assert(orderRgbPixelsByContrast(['255,0,0']).toString() == '[R@255,0,0#255]');
  assert(orderRgbPixelsByContrast(['0,0,255','255,0,0']).first == 'B@0,0,255#255');
  print('All tests passed!');
}

