@pragma('vm:entry-point')
String morseSignalOnDay(String pattern, int cycleStartDay, int queryDay) {
  if (pattern.isEmpty || queryDay < cycleStartDay) {
    return "";
  }

  int cycleLength = 3;
  for (int i = 0; i < pattern.length; i++) {
    if (pattern[i] == '.') {
      cycleLength += 1;
    } else if (pattern[i] == '-') {
      cycleLength += 3;
    }

    if (i < pattern.length - 1) {
      cycleLength += 1;
    }
  }

  int offset = (queryDay - cycleStartDay) % cycleLength;
  int position = 0;

  for (int i = 0; i < pattern.length; i++) {
    int duration = pattern[i] == '.' ? 1 : 3;

    if (offset >= position && offset < position + duration) {
      return pattern[i];
    }

    position += duration;

    if (i < pattern.length - 1) {
      if (offset == position) {
        return "|";
      }
      position += 1;
    }
  }

  return "/";
}

