List<String> replayScaledRecipeLog(List<String> operations) {
  Map<String, int> totals = {};
  List<int> scaleStack = [1];
  List<Map<String, int>> totalHistory = [];
  List<List<int>> scaleHistory = [];

  for (String op in operations) {
    if (op == 'UNDO') {
      if (totalHistory.isNotEmpty) {
        totals = totalHistory.removeLast();
        scaleStack = scaleHistory.removeLast();
      }
      continue;
    }

    totalHistory.add(Map<String, int>.from(totals));
    scaleHistory.add(List<int>.from(scaleStack));

    List<String> parts = op.split(' ');

    if (parts[0] == 'BEGIN') {
      int factor = int.parse(parts[1]);
      scaleStack.add(scaleStack.last * factor);
    } else if (parts[0] == 'END') {
      if (scaleStack.length > 1) {
        scaleStack.removeLast();
      }
    } else if (parts[0] == 'ADD') {
      String ingredient = parts[1];
      int amount = int.parse(parts[2]) * scaleStack.last;
      totals[ingredient] = (totals[ingredient] ?? 0) + amount;
    }
  }

  List<String> result = [];
  List<String> keys = totals.keys.toList()..sort();

  for (String key in keys) {
    result.add('$key=${totals[key]}');
  }

  return result;
}

