  assert(replayScaledRecipeLog(['ADD sugar 2']).toString() == '[sugar=2]');
  assert(replayScaledRecipeLog(['BEGIN 3', 'ADD flour 2', 'END']).length == 1);
  assert(replayScaledRecipeLog(['ADD salt 1', 'UNDO']).toString() == '[]');
  print('All tests passed!');
}

