  expect(candidate([[5, 1, 5], [5, 100, 5], [5, 1, 5]]).toString(), '[0, 0, 0]');
  expect(candidate([[8, 1, 9], [7, 2, 10], [6, 3, 11], [5, 4, 12]]).toString(), '[1, 1, 1, 1]');
  expect(candidate([[1, 100, 1], [100, 2, 100], [1, 3, 1]]).toString(), '[0, 1, 0]');
