@pragma('vm:entry-point')
List<String> enumerateBatteryChargeCycles(List<int> cycleUnits, int capacity, int targetCharge) {
  final Set<String> results = <String>{};

  void search(
    int index,
    int charge,
    bool skippedLast,
    List<String> steps,
  ) {
    if (index == cycleUnits.length) {
      if (charge == targetCharge) {
        if (steps.isEmpty) {
          results.add('idle');
        } else {
          results.add(steps.join(','));
        }
      }
      return;
    }

    final int unit = cycleUnits[index];

    if (charge + unit <= capacity) {
      steps.add('C$unit');
      search(index + 1, charge + unit, false, steps);
      steps.removeLast();
    }

    if (charge - unit >= 0) {
      steps.add('D$unit');
      search(index + 1, charge - unit, false, steps);
      steps.removeLast();
    }

    if (!skippedLast) {
      steps.add('S');
      search(index + 1, charge, true, steps);
      steps.removeLast();
    }
  }

  search(0, 0, false, <String>[]);

  final List<String> ordered = results.toList();
  ordered.sort();
  return ordered;
}

@pragma('vm:entry-point')
void main() {
  assert(enumerateBatteryChargeCycles([], 4, 0).toString() == '[idle]');
  assert(enumerateBatteryChargeCycles([1], 1, 1).length == 1);
  assert(enumerateBatteryChargeCycles([2, 1], 3, 1).toString() == '[C2,D1, S,C1]');
  print('All tests passed!');
}

