@pragma('vm:entry-point')
Set<int> deriveShelfCodeIndexes(List<String> shelfCodes, int threshold) {
  final Set<int> indexes = <int>{};

  for (final code in shelfCodes) {
    final parts = code.split('-');
    if (parts.length != 2 || parts[0].isEmpty || parts[1].isEmpty) {
      continue;
    }

    final int letterScore = parts[0]
        .toUpperCase()
        .codeUnits
        .fold(0, (sum, unit) {
      if (unit >= 65 && unit <= 90) {
        return sum + (unit - 64);
      }
      return sum;
    });

    int digitScore = 0;
    for (final unit in parts[1].codeUnits) {
      if (unit >= 48 && unit <= 57) {
        digitScore += unit - 48;
      }
    }

    if (digitScore == 0 && letterScore < threshold) {
      continue;
    }

    final int combined = letterScore.isEven
        ? letterScore - digitScore
        : letterScore + digitScore;

    if (combined >= threshold) {
      indexes.add(combined);
    } else if (combined < 0) {
      indexes.add(-combined);
    }
  }

  return indexes;
}

@pragma('vm:entry-point')
void main() {
  assert(deriveShelfCodeIndexes(["A-90"], 5).toString() == '{10}');
  assert(deriveShelfCodeIndexes(["AA-99", "AA-99"], 5).length == 1);
  assert(deriveShelfCodeIndexes(["ABC-12"], 7).isEmpty);
  print('All tests passed!');
}

tests:
