  expect(candidate(["AA-99", "AA-99", "B-11"], 5).length, 1);
  expect(candidate(["BAD", "-12", "AB-"], 1).isEmpty, true);
  expect(candidate(["ABC-12", "D-10"], 7).toString(), '{}');
  expect(candidate(["Z-9", "LM-44", "K-222"], 20).toString(), '{33}');
  expect(candidate(["AZ-999", "M-50"], 10).contains(54), true);
  expect(candidate(["AZ-999", "M-50"], 10).length, 2);
}

