@pragma('vm:entry-point')
Set<int> theaterResidueSeats(int rows, int seatsPerRow, int base, int modulus) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }

  int reversedBaseValue(int n, int radix) {
    int value = 0;
    while (n > 0) {
      value = value * radix + (n % radix);
      n ~/= radix;
    }
    return value;
  }

  Set<int> result = <int>{};
  if (rows <= 0 || seatsPerRow <= 0 || base < 2 || modulus < 1) {
    return result;
  }

  int totalSeats = rows * seatsPerRow;

  for (int seat = 1; seat <= totalSeats; seat++) {
    int mirrored = reversedBaseValue(seat, base);
    if (!isPrime(mirrored)) continue;
    if (gcd(seat, modulus) != 1) continue;

    int temp = seat;
    int digitGcd = 0;
    while (temp > 0) {
      int digit = temp % base;
      if (digit != 0) {
        digitGcd = digitGcd == 0 ? digit : gcd(digitGcd, digit);
      }
      temp ~/= base;
    }

    int row = ((seat - 1) ~/ seatsPerRow) + 1;

    if (digitGcd == 1 &&
        (mirrored + row) % modulus == seat % modulus) {
      result.add(seat);
    }
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(theaterResidueSeats(2, 5, 2, 3).length == 1);
  assert(theaterResidueSeats(0, 8, 10, 3).isEmpty);
  assert(theaterResidueSeats(1, 20, 10, 1).length == 5);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = theaterResidueSeats;

  expect(candidate(2, 5, 2, 3).toString(), '{10}');
  expect(candidate(3, 4, 3, 5).toString(), '{7}');
  expect(candidate(2, 10, 10, 7).toString(), '{17}');
  expect(candidate(1, 20, 10, 1).toString(), '{11, 13, 14, 16, 17}');
  expect(candidate(0, 8, 10, 3).isEmpty, true);
  expect(candidate(1, 1, 2, 1).isEmpty, true);
}

